export const CONTENT = JSON.parse("{\"id\":\"rest\",\"docs\":{\"programming/01-syntax\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"编程\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 语法\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"语法规定哪些符号串是合法程序，以及它们组成怎样的结构。它不决定表达式何时求值，也不决定类型是否合法。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"这一页补哪一块 {#syntax-scope}\",\"id\":\"h-1\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"编程入门 02\",\"href\":\"../../programming-basics/02-core-concepts/\"},{\"t\":\"text\",\"v\":\" 写声明、表达式和语句怎么写出来。本页只问：定义凭什么说这一串记号是一棵结构，而不是另一棵。不写词法分析器或语法分析器怎么实现，也不罗列 C 或 Java 的全部语法。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"理论基础 12\",\"href\":\"../../cs-theory/12-automata-languages/\"},{\"t\":\"text\",\"v\":\" 给出自动机和文法的定义。记号更接近正则语言能描述的那一层，短语结构更接近上下文无关文法。那是选读，不是本页前置。本页不证明泵引理。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"先切成记号，再组成短语 {#syntax-tokens}\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"程序先被切成记号，再组成声明和表达式。C 的翻译阶段把源文件分解成预处理记号和空白（含注释）；每条注释被换成一个空格，换行保留。空白用来分开记号。除非语言另有规定，例如字符串字面量里面的字符属于那个记号，空白和注释不进入后面的短语结构。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"Java 同样先做词法结构，再做句法。本页用 C 和 Java 说明这种默认情况。有的语言把缩进写进语法，那是那份定义自己的规定，不是这里的结论。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"写法可以不同，结构可以相同 {#syntax-abstract}\",\"id\":\"h-3\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"具体语法是源文件里的写法，包括括号、关键字和分隔符。抽象结构是这些记号组成的树：哪个运算符是父节点，哪些表达式是它的操作数。定义关心的是这棵结构，不只是字符是否逐个相同。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"code\",\"v\":\"a + b\"},{\"t\":\"text\",\"v\":\" 和 \"},{\"t\":\"code\",\"v\":\"(a + b)\"},{\"t\":\"text\",\"v\":\" 可以对应同一次加法。多出来的括号是具体语法。它们没有在这个例子里变成另一个运算符。教材用「具体语法 / 抽象语法」这对词讲这件事。C 和 Java 的文本写的是自己的文法，不要把教材里的树直接当成标准条款。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"歧义是两棵结构，不是读着别扭 {#syntax-ambiguity}\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"歧义是指同一串记号对应不止一棵结构。优先级和结合性属于定义，用来规定哪一棵结构合法。它们不是排版习惯。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"悬挂的 \"},{\"t\":\"code\",\"v\":\"else\"},{\"t\":\"text\",\"v\":\" 是一个短例子。下面这一串可以让人想到两棵树：\"},{\"t\":\"code\",\"v\":\"else\"},{\"t\":\"text\",\"v\":\" 属于外层的 \"},{\"t\":\"code\",\"v\":\"if\"},{\"t\":\"text\",\"v\":\"，或者属于内层的 \"},{\"t\":\"code\",\"v\":\"if\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"code\",\"lang\":\"c\",\"code\":\"if (a)\\n    if (b)\\n        f();\\nelse\\n    g();\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"C 的 \"},{\"t\":\"code\",\"v\":\"if\"},{\"t\":\"text\",\"v\":\" 语句条款写明：\"},{\"t\":\"code\",\"v\":\"else\"},{\"t\":\"text\",\"v\":\" 与词法上最近的、语法上允许配对的 \"},{\"t\":\"code\",\"v\":\"if\"},{\"t\":\"text\",\"v\":\" 连在一起。因此这里只有一棵合法的结构，\"},{\"t\":\"code\",\"v\":\"else\"},{\"t\":\"text\",\"v\":\" 属于内层。缩进写成外层的样子，也改变不了这棵树。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"Java 把同一件事写进文法。JLS 14.5 说明，\"},{\"t\":\"code\",\"v\":\"else\"},{\"t\":\"text\",\"v\":\" 属于它可能隶属的最内层 \"},{\"t\":\"code\",\"v\":\"if\"},{\"t\":\"text\",\"v\":\"。\"},{\"t\":\"code\",\"v\":\"else\"},{\"t\":\"text\",\"v\":\" 前面的子语句必须是不会悬着一个短 \"},{\"t\":\"code\",\"v\":\"if\"},{\"t\":\"text\",\"v\":\" 的语句。执行方式并不因为这条限制而改变；限制只用来消去第二种结构。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"运算符的优先级也是结构规则。C 和 Java 的表达式文法把乘除放在比加减更靠近叶子的一层，所以 \"},{\"t\":\"code\",\"v\":\"a + b * c\"},{\"t\":\"text\",\"v\":\" 的父节点是加法，右操作数才是乘法。这不是「先乘后加比较好看」。换一种语言，如果它的文法把这两层写反了，结构就不同。不能从 C 或 Java 推出所有语言都如此。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"合法的结构还没有含义 {#syntax-not-meaning}\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"code\",\"v\":\"x + y\"},{\"t\":\"text\",\"v\":\" 能构成加法表达式，只说明这串记号有一棵加法结构。它还不决定两个操作数何时求值，加法会不会溢出，也不决定 \"},{\"t\":\"code\",\"v\":\"x\"},{\"t\":\"text\",\"v\":\" 和 \"},{\"t\":\"code\",\"v\":\"y\"},{\"t\":\"text\",\"v\":\" 的类型是否允许相加。求值顺序在\"},{\"t\":\"link\",\"v\":\"语义\",\"href\":\"../02-semantics/\"},{\"t\":\"text\",\"v\":\"，类型在\"},{\"t\":\"link\",\"v\":\"类型系统\",\"href\":\"../03-types/\"},{\"t\":\"text\",\"v\":\"，溢出算不算已定义在\"},{\"t\":\"link\",\"v\":\"求值与内存模型\",\"href\":\"../04-evaluation-memory/\"},{\"t\":\"text\",\"v\":\"。能通过语法这一关，只表示结构合法。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"常见误读 {#syntax-misreadings}\",\"id\":\"h-6\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"「能编译通过，语法就规定了运行结果。」编译器接受这棵结构，只说明实现认为它落在语法和后续约束里。结果仍要看语义、类型和内存条款有没有给出保证。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「换一种缩进或换行，含义一定变。」在 C 和 Java 里，空白分开记号，不选择 \"},{\"t\":\"code\",\"v\":\"else\"},{\"t\":\"text\",\"v\":\" 属于哪一个 \"},{\"t\":\"code\",\"v\":\"if\"},{\"t\":\"text\",\"v\":\"。只有语言把空白写进语法时，缩进才是结构的一部分。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「优先级是风格问题，不是定义。」文法把哪一个运算符放在父节点，就是结构定义。风格指南不能改写这条规则。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"可选核对 {#syntax-check}\",\"id\":\"h-7\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"上一节已经写完哪一棵树合法。这两问只核对边界。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"把悬挂 \"},{\"t\":\"code\",\"v\":\"else\"},{\"t\":\"text\",\"v\":\" 的例子重新缩进，使 \"},{\"t\":\"code\",\"v\":\"else\"},{\"t\":\"text\",\"v\":\" 在视觉上对齐外层 \"},{\"t\":\"code\",\"v\":\"if\"},{\"t\":\"text\",\"v\":\"。C 的合法结构变了吗？\"}],\"n\":1},{\"inlines\":[{\"t\":\"code\",\"v\":\"x + y\"},{\"t\":\"text\",\"v\":\" 是合法的加法表达式。这是否已经规定两个操作数谁先求值？\"}],\"n\":2}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"没有变。C 规定 \"},{\"t\":\"code\",\"v\":\"else\"},{\"t\":\"text\",\"v\":\" 属于词法上最近的那个允许配对的 \"},{\"t\":\"code\",\"v\":\"if\"},{\"t\":\"text\",\"v\":\"。缩进不是这条规则的输入。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"没有。语法只给出加法这棵结构。操作数的求值顺序是语义条款，而且 C 与 Java 的规定并不相同。\"}],\"n\":2}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引 {#syntax-sources}\",\"id\":\"h-8\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"ISO/IEC 9899:2024\",\"href\":\"https://www.iso.org/standard/82075.html\"},{\"t\":\"text\",\"v\":\" — C 的语言定义。翻译阶段把注释换成空格；\"},{\"t\":\"code\",\"v\":\"if\"},{\"t\":\"text\",\"v\":\" 语句条款规定 \"},{\"t\":\"code\",\"v\":\"else\"},{\"t\":\"text\",\"v\":\" 的配对。引用的是结构规则，不是某个编译器的扩展。可读文本：\"},{\"t\":\"link\",\"v\":\"N3220\",\"href\":\"https://www.open-std.org/jtc1/sc22/wg14/www/docs/n3220.pdf\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"JLS 14.5 Statements\",\"href\":\"https://docs.oracle.com/javase/specs/jls/se21/html/jls-14.html#jls-14.5\"},{\"t\":\"text\",\"v\":\" — Java 用文法消去悬挂 \"},{\"t\":\"code\",\"v\":\"else\"},{\"t\":\"text\",\"v\":\"：\"},{\"t\":\"code\",\"v\":\"else\"},{\"t\":\"text\",\"v\":\" 属于最内层的 \"},{\"t\":\"code\",\"v\":\"if\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"JLS 第 2 章 Grammars 与第 19 章 Syntax\",\"href\":\"https://docs.oracle.com/javase/specs/jls/se21/html/jls-2.html\"},{\"t\":\"text\",\"v\":\" — 词法与句法的入口。表达式文法分层表示优先级。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Michael L. Scott, Programming Language Pragmatics\",\"href\":\"https://www.cs.rochester.edu/~scott/pragmatics/\"},{\"t\":\"text\",\"v\":\" — 「具体语法 / 抽象语法」和「歧义」的概念对照。书中的树不是 C 或 Java 的条款。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"编程入门 02 核心概念\",\"href\":\"../../programming-basics/02-core-concepts/\"},{\"t\":\"text\",\"v\":\" — 声明、表达式和语句怎么写。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"理论基础 12 自动机与形式语言\",\"href\":\"../../cs-theory/12-automata-languages/\"},{\"t\":\"text\",\"v\":\" — 正则与文法的定义。选读，不是前置。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"返回编程\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：语义\",\"href\":\"../02-semantics/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"这一页补哪一块 {#syntax-scope}\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"先切成记号，再组成短语 {#syntax-tokens}\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"写法可以不同，结构可以相同 {#syntax-abstract}\"},{\"id\":\"h-4\",\"level\":2,\"text\":\"歧义是两棵结构，不是读着别扭 {#syntax-ambiguity}\"},{\"id\":\"h-5\",\"level\":2,\"text\":\"合法的结构还没有含义 {#syntax-not-meaning}\"},{\"id\":\"h-6\",\"level\":2,\"text\":\"常见误读 {#syntax-misreadings}\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"可选核对 {#syntax-check}\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"资料索引 {#syntax-sources}\"}]},\"programming/02-semantics\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"编程\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 语义\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"语义给已经合法的结构赋予含义：名字绑到哪一个实体，表达式如何一步步变成值，或者如何改变状态。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"这一页补哪一块 {#semantics-scope}\",\"id\":\"h-1\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"编程入门 02\",\"href\":\"../../programming-basics/02-core-concepts/\"},{\"t\":\"text\",\"v\":\" 写函数和块怎么声明。\"},{\"t\":\"link\",\"v\":\"编程入门 03\",\"href\":\"../../programming-basics/03-memory-and-data/\"},{\"t\":\"text\",\"v\":\" 写对象占的存储。本页不重讲布局，也不重讲函数怎么写。这里用操作型的说法：一步一步看绑定和求值。不写指称语义。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"Java 01\",\"href\":\"../../java/01-language-basics/\"},{\"t\":\"text\",\"v\":\" 写对象引用和方法调用。本页只取其中的传递规则。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"作用域是文本，生存期是时间 {#semantics-scope-lifetime}\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"绑定、作用域、生存期是三件事。绑定说的是一个名字这次指向哪个实体。作用域是这个名字在程序文本里可见的区域。生存期是对象在一次执行中存在的那段时间。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"C 把作用域定义为程序文本中的区域：标识符只在它的作用域里可见。块作用域延伸到对应块的结尾。生存期则是执行中为对象保留存储的那段时间。进入被调用的函数会挂起当前块，但不会结束当前块。块被递归进入时，每次都会新建一个对象。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"用同一个局部变量把两件事拆开：\"}]},{\"t\":\"code\",\"lang\":\"c\",\"code\":\"void f(int n) {\\n    int x = n;\\n    if (n > 0)\\n        f(n - 1);\\n}\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"code\",\"v\":\"f(1)\"},{\"t\":\"text\",\"v\":\" 调用 \"},{\"t\":\"code\",\"v\":\"f(0)\"},{\"t\":\"text\",\"v\":\" 时，外层那次调用的 \"},{\"t\":\"code\",\"v\":\"x\"},{\"t\":\"text\",\"v\":\" 仍然活着，因为外层块还没结束。内层文本里的名字 \"},{\"t\":\"code\",\"v\":\"x\"},{\"t\":\"text\",\"v\":\" 指的是内层新建的那个对象，看不见外层那个。名字的可见范围没有变长，对象的存在时间也没有跟着内层文本一起结束。所以「这个名字在这里看不见」推不出「那个对象已经没了」。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"Java 的作用域同样由声明在文本中的位置决定。一个局部变量的声明覆盖它可见的那段正文；这不是「这块内存还要留多久」。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"词法作用域不看谁在调用 {#semantics-lexical}\",\"id\":\"h-3\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"静态作用域，也叫词法作用域，按文本上包围这段代码的声明来绑定名字。动态作用域按调用当时栈上最近的同名声明来绑定。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"下面不是一段能在标准 C 里编译的嵌套函数，只用来对照两条规则。\"},{\"t\":\"code\",\"v\":\"g\"},{\"t\":\"text\",\"v\":\" 的正文不声明 \"},{\"t\":\"code\",\"v\":\"x\"},{\"t\":\"text\",\"v\":\"，\"},{\"t\":\"code\",\"v\":\"f\"},{\"t\":\"text\",\"v\":\" 和最外层各有一个 \"},{\"t\":\"code\",\"v\":\"x\"},{\"t\":\"text\",\"v\":\"。调用顺序是最外层调用 \"},{\"t\":\"code\",\"v\":\"f\"},{\"t\":\"text\",\"v\":\"，\"},{\"t\":\"code\",\"v\":\"f\"},{\"t\":\"text\",\"v\":\" 再调用 \"},{\"t\":\"code\",\"v\":\"g\"},{\"t\":\"text\",\"v\":\"，\"},{\"t\":\"code\",\"v\":\"g\"},{\"t\":\"text\",\"v\":\" 读取 \"},{\"t\":\"code\",\"v\":\"x\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"词法作用域：\"},{\"t\":\"code\",\"v\":\"g\"},{\"t\":\"text\",\"v\":\" 的正文被最外层的 \"},{\"t\":\"code\",\"v\":\"x\"},{\"t\":\"text\",\"v\":\" 包围，没有被 \"},{\"t\":\"code\",\"v\":\"f\"},{\"t\":\"text\",\"v\":\" 的正文包围。\"},{\"t\":\"code\",\"v\":\"g\"},{\"t\":\"text\",\"v\":\" 读到的是最外层那个 \"},{\"t\":\"code\",\"v\":\"x\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"动态作用域：查找沿着这次调用走。\"},{\"t\":\"code\",\"v\":\"g\"},{\"t\":\"text\",\"v\":\" 的调用者 \"},{\"t\":\"code\",\"v\":\"f\"},{\"t\":\"text\",\"v\":\" 有 \"},{\"t\":\"code\",\"v\":\"x\"},{\"t\":\"text\",\"v\":\"，于是读到 \"},{\"t\":\"code\",\"v\":\"f\"},{\"t\":\"text\",\"v\":\" 里那个 \"},{\"t\":\"code\",\"v\":\"x\"},{\"t\":\"text\",\"v\":\"。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"两条规则把同一个名字绑到不同的对象。C 和 Java 采用词法作用域：看见哪个声明，由名字出现的文本位置决定，不由谁调用决定。动态作用域只作对照，不是这两份定义里的已定义行为。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"参数传递复制的是值 {#semantics-parameters}\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"参数传递是语义规则，要写清复制的是什么。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"C 的函数调用条款规定：准备调用时先求值实参，再把对应实参的值赋给参数。参数是函数里的对象，改参数就是改这个对象，不是改调用者的对象。下面的 \"},{\"t\":\"code\",\"v\":\"rebind\"},{\"t\":\"text\",\"v\":\" 返回后，调用者的 \"},{\"t\":\"code\",\"v\":\"n\"},{\"t\":\"text\",\"v\":\" 仍是调用前的值。\"},{\"t\":\"code\",\"v\":\"via_pointer\"},{\"t\":\"text\",\"v\":\" 写的是指针值所指的对象；被复制的是指针值，不是把调用者的变量改绑到别处。\"}]},{\"t\":\"code\",\"lang\":\"c\",\"code\":\"void rebind(int x) { x = 2; }\\nvoid via_pointer(int *p) { *p = 2; }\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"Java 也是把实参的值用来初始化一次调用里新建的参数变量。引用类型的值是引用，不是把对象再复制一份。被调方法给参数重新赋值，改的是参数变量，调用者的变量仍指向原来的对象。被调方法如果修改了那个对象的字段，调用者能看见，因为两边的引用值指向同一对象。这不是「被调方法把调用者的变量改绑了」。因此不能把 Java 概括成引用传递。引用传递通常指被调方能让调用者的变量改指另一个对象。Java 的方法做不到这件事，除非调用者传来的本来就是一个可以被改字段的容器。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这个条件只覆盖这里引用的 C 函数调用条款和 JLS 的参数初始化。不要写成所有语言都按值传递。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"求值顺序是语义，未指定不是未定义 {#semantics-order}\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"表达式的值，和它在求值过程中产生的副作用，要分开写。定义可以规定副作用的顺序，也可以明确不规定。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"Java 对多数二元运算规定从左到右：左操作数看起来完整求值之后，右操作数才开始。\"},{\"t\":\"code\",\"v\":\"&&\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"||\"},{\"t\":\"text\",\"v\":\" 和 \"},{\"t\":\"code\",\"v\":\"?:\"},{\"t\":\"text\",\"v\":\" 是写明的例外，未用到的那一侧可以不求值。方法调用的实参列表也是从左到右，每个实参完整求值后才轮到它右边的实参。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"C 没有这条总的从左到右规定。标准自己把「函数实参的求值顺序」当作未指定行为的例子：文档给出多于一种可能，并且不要求每次选择同一种。未指定仍是有边界的。表达式条款另有一条：对同一个标量对象，若一个副作用相对另一个副作用或相对使用该值的运算是无序的，行为是未定义。未指定是「几种结果都合法」。未定义是「这份定义不再给保证」。结果因编译器而异，本身区分不了这两种。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"十步以内的两种历史 {#semantics-derivation}\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"设 \"},{\"t\":\"code\",\"v\":\"a()\"},{\"t\":\"text\",\"v\":\" 打印 \"},{\"t\":\"code\",\"v\":\"A\"},{\"t\":\"text\",\"v\":\" 并返回 \"},{\"t\":\"code\",\"v\":\"1\"},{\"t\":\"text\",\"v\":\"，\"},{\"t\":\"code\",\"v\":\"b()\"},{\"t\":\"text\",\"v\":\" 打印 \"},{\"t\":\"code\",\"v\":\"B\"},{\"t\":\"text\",\"v\":\" 并返回 \"},{\"t\":\"code\",\"v\":\"2\"},{\"t\":\"text\",\"v\":\"。两者不修改同一个标量对象。表达式是 \"},{\"t\":\"code\",\"v\":\"a() + b()\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"Java 规定左操作数先完整求值：\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"进入 \"},{\"t\":\"code\",\"v\":\"a()\"},{\"t\":\"text\",\"v\":\"。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"打印 \"},{\"t\":\"code\",\"v\":\"A\"},{\"t\":\"text\",\"v\":\"。\"}],\"n\":2},{\"inlines\":[{\"t\":\"code\",\"v\":\"a()\"},{\"t\":\"text\",\"v\":\" 得到值 \"},{\"t\":\"code\",\"v\":\"1\"},{\"t\":\"text\",\"v\":\"。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"进入 \"},{\"t\":\"code\",\"v\":\"b()\"},{\"t\":\"text\",\"v\":\"。\"}],\"n\":4},{\"inlines\":[{\"t\":\"text\",\"v\":\"打印 \"},{\"t\":\"code\",\"v\":\"B\"},{\"t\":\"text\",\"v\":\"。\"}],\"n\":5},{\"inlines\":[{\"t\":\"code\",\"v\":\"b()\"},{\"t\":\"text\",\"v\":\" 得到值 \"},{\"t\":\"code\",\"v\":\"2\"},{\"t\":\"text\",\"v\":\"。\"}],\"n\":6},{\"inlines\":[{\"t\":\"text\",\"v\":\"把 \"},{\"t\":\"code\",\"v\":\"1\"},{\"t\":\"text\",\"v\":\" 和 \"},{\"t\":\"code\",\"v\":\"2\"},{\"t\":\"text\",\"v\":\" 相加，表达式的值是 \"},{\"t\":\"code\",\"v\":\"3\"},{\"t\":\"text\",\"v\":\"。\"}],\"n\":7}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"可见历史只有一种：输出 \"},{\"t\":\"code\",\"v\":\"AB\"},{\"t\":\"text\",\"v\":\"，值是 \"},{\"t\":\"code\",\"v\":\"3\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"C 不规定这两个操作数谁先求值。在两者不冲突的前提下，下面两种历史都合法：\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"先完成 \"},{\"t\":\"code\",\"v\":\"a()\"},{\"t\":\"text\",\"v\":\" 再完成 \"},{\"t\":\"code\",\"v\":\"b()\"},{\"t\":\"text\",\"v\":\"，输出 \"},{\"t\":\"code\",\"v\":\"AB\"},{\"t\":\"text\",\"v\":\"，值是 \"},{\"t\":\"code\",\"v\":\"3\"},{\"t\":\"text\",\"v\":\"。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"先完成 \"},{\"t\":\"code\",\"v\":\"b()\"},{\"t\":\"text\",\"v\":\" 再完成 \"},{\"t\":\"code\",\"v\":\"a()\"},{\"t\":\"text\",\"v\":\"，输出 \"},{\"t\":\"code\",\"v\":\"BA\"},{\"t\":\"text\",\"v\":\"，值是 \"},{\"t\":\"code\",\"v\":\"3\"},{\"t\":\"text\",\"v\":\"。\"}],\"n\":2}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"每种历史里每个函数只调用一次。值相同，副作用的顺序可以不同。这仍是未指定，不是未定义：标准允许这些选择，并没有说程序可以有任意行为。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"若把例子改成在同一个表达式里对同一个标量无序地修改两次，表达式条款把它定为未定义。那时就不能再说「两种结果都合法，只是不知道是哪一种」。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"常见误读 {#semantics-misreadings}\",\"id\":\"h-7\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"「作用域就是变量在内存里待多久。」作用域是名字在文本中可见的范围。生存期是对象存在的时间。递归调用里，外层对象还活着，内层文本已经看不见它。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「Java 传递对象就是引用传递。」传递的是引用的值。被调方法不能把调用者的变量改绑到另一个对象。能改的是对象里的状态，那是因为两边持有指向它的引用值。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「结果因编译器而异，所以这是未定义行为。」先看标准是给出了几种合法选择（未指定），还是对这种程序不再给任何保证（未定义）。实参求值顺序是前一种；对同一标量的无序副作用是后一种。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"可选核对 {#semantics-check}\",\"id\":\"h-8\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"定义已经写在上面。这两问只核对两个容易并在一起的概念。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"code\",\"v\":\"f(1)\"},{\"t\":\"text\",\"v\":\" 正在执行内层的 \"},{\"t\":\"code\",\"v\":\"f(0)\"},{\"t\":\"text\",\"v\":\"。外层那次调用的 \"},{\"t\":\"code\",\"v\":\"x\"},{\"t\":\"text\",\"v\":\" 已经结束生存期了吗？内层的名字 \"},{\"t\":\"code\",\"v\":\"x\"},{\"t\":\"text\",\"v\":\" 指的是哪一个对象？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"Java 方法把一个引用类型的参数赋成另一个对象。调用者的变量会改绑吗？\"}],\"n\":2}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"外层对象的生存期还没结束，因为外层块被调用挂起，没有结束。内层的名字 \"},{\"t\":\"code\",\"v\":\"x\"},{\"t\":\"text\",\"v\":\" 指内层新建的对象。看不见外层的名字，不等于外层对象已经消失。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"不会。参数变量被赋了新的引用值，调用者的变量仍是调用前那个引用值。这不是引用传递。\"}],\"n\":2}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引 {#semantics-sources}\",\"id\":\"h-9\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"JLS 15.7 Evaluation Order\",\"href\":\"https://docs.oracle.com/en/java/javase/26/docs/specs/jls/jls-15.html#jls-15.7\"},{\"t\":\"text\",\"v\":\" — 多数运算符从左到右；\"},{\"t\":\"code\",\"v\":\"&&\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"||\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"?:\"},{\"t\":\"text\",\"v\":\" 是写明的例外。15.7.4 规定实参列表从左到右。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"JLS 15.12.4 Run-Time Evaluation of Method Invocation\",\"href\":\"https://docs.oracle.com/en/java/javase/26/docs/specs/jls/jls-15.html#jls-15.12.4\"},{\"t\":\"text\",\"v\":\" — 方法调用先处理目标，再求值实参，然后才进入方法体。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"JLS 8.4.1 Formal Parameters\",\"href\":\"https://docs.oracle.com/javase/specs/jls/se21/html/jls-8.html#jls-8.4.1\"},{\"t\":\"text\",\"v\":\" — 实参的值初始化本次调用新建的参数变量。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"ISO/IEC 9899:2024\",\"href\":\"https://www.iso.org/standard/82075.html\"},{\"t\":\"text\",\"v\":\" — 作用域是文本区域；生存期是为对象保留存储的执行区间；函数调用把实参的值赋给参数；实参求值顺序是未指定行为的例子；对同一标量的无序副作用是未定义行为。可读文本：\"},{\"t\":\"link\",\"v\":\"N3220\",\"href\":\"https://www.open-std.org/jtc1/sc22/wg14/www/docs/n3220.pdf\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Michael L. Scott, Programming Language Pragmatics\",\"href\":\"https://www.cs.rochester.edu/~scott/pragmatics/\"},{\"t\":\"text\",\"v\":\" — 词法作用域与动态作用域的概念对照。动态作用域不是 C 或 Java 的条款。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"编程入门 02\",\"href\":\"../../programming-basics/02-core-concepts/\"},{\"t\":\"text\",\"v\":\" — 函数与块怎么写。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"编程入门 03\",\"href\":\"../../programming-basics/03-memory-and-data/\"},{\"t\":\"text\",\"v\":\" — 对象占的存储。本页不重讲布局。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Java 01 语言基础\",\"href\":\"../../java/01-language-basics/\"},{\"t\":\"text\",\"v\":\" — 对象引用与方法调用。本页只取传递规则。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：语法\",\"href\":\"../01-syntax/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回编程\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：类型系统\",\"href\":\"../03-types/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"这一页补哪一块 {#semantics-scope}\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"作用域是文本，生存期是时间 {#semantics-scope-lifetime}\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"词法作用域不看谁在调用 {#semantics-lexical}\"},{\"id\":\"h-4\",\"level\":2,\"text\":\"参数传递复制的是值 {#semantics-parameters}\"},{\"id\":\"h-5\",\"level\":2,\"text\":\"求值顺序是语义，未指定不是未定义 {#semantics-order}\"},{\"id\":\"h-6\",\"level\":2,\"text\":\"十步以内的两种历史 {#semantics-derivation}\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"常见误读 {#semantics-misreadings}\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"可选核对 {#semantics-check}\"},{\"id\":\"h-9\",\"level\":2,\"text\":\"资料索引 {#semantics-sources}\"}]},\"programming/03-types\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"编程\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 类型系统\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"类型是语言对值和表达式的分类，并据此在编译期或运行期拒绝一些程序。通过检查不等于程序正确。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"这一页补哪一块 {#types-scope}\",\"id\":\"h-1\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"编程入门 02\",\"href\":\"../../programming-basics/02-core-concepts/\"},{\"t\":\"text\",\"v\":\" 写 C 里的类型和转换怎么用。\"},{\"t\":\"link\",\"v\":\"Java 01\",\"href\":\"../../java/01-language-basics/\"},{\"t\":\"text\",\"v\":\" 写 Java 的类型从哪里来。\"},{\"t\":\"link\",\"v\":\"Java 03\",\"href\":\"../../java/03-core-advanced/\"},{\"t\":\"text\",\"v\":\" 写泛型和擦除怎么用。本页不列类型关键字，也不重写泛型章。这里只问：检查在什么时候拒绝程序，拒绝失败时语言保证什么，以及这套规则故意留了哪些口子。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"不引入完整的类型论，也不给形式化证明。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"检查发生在翻译时，还是发生在运算时 {#types-when}\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"静态检查在翻译或装载这批程序时拒绝它。失败的保证是：程序不会以「已通过检查」的身份进入后面的执行。动态检查在某一次运算真正发生时拒绝它。失败的保证是一份已经写明的错误，例如抛出某个异常，而不是把整份语言定义撤回。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"C 的类型约束能在翻译期诊断一部分不匹配，但检查比 Java 弱，而且强制转换可以绕过「这个值不该当那种对象用」。一个通过了翻译的 C 程序，仍可能在后面的条款里落入未定义行为。Java 在语言边界上更接近另一种约定：对不上的转换，要么翻译时就是错误，要么在运行时抛出写明的异常，而不是把「把整数当指针用」仍称作已定义。这是两份定义的对照，不是所有语言的共同底线。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"Python 速成\",\"href\":\"../../ai/00-python-bridge/\"},{\"t\":\"text\",\"v\":\" 只作动态检查的对照：值在运算发生时仍带有分类，失败是一次明确的错误。动态检查不是「没有类型」。本页不写 Python 教程。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"健全是有条件的承诺 {#types-soundness}\",\"id\":\"h-3\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"类型健全的直觉说法是：在这套规则的前提都成立时，通过检查的程序不会以定义禁止的方式卡住。例如，不会把一个整数当作指针去用，还把这次使用称为已定义行为。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这个承诺依赖前提。规则没有覆盖到的转换、被程序员明确要求跳过的检查，都不在承诺里面。本页不把这句话写成定理，也不复述 progress 和 preservation 的证明。概念来自类型系统教材里的健全性直觉，资料索引会标明这一点。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"比的是名字，还是形状 {#types-nominal}\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"名义类型比较的是声明的名字。结构类型比较的是字段和方法组成的形状，两个没有共同声明的类型，只要形状相符就可以被当成同一种。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"Java 的类和接口是名义的。JLS 规定，两个引用类型在编译期是否为同一类型，要看它们是否来自同一声明：二元名相同，类型实参也相同。只是方法列表长得像，并不能使两个类变成同一个类型。本页只建立这个对照，不展开别的语言里的结构类型。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"通过检查没有证明程序正确 {#types-not-correct}\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"类型规则拒绝的是它写明要拒绝的那些程序。它不因此保证下面任何一条，除非该语言另有条款：\"}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"程序会终止。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"程序只使用有上限的内存或时间。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"程序没有数据竞争。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"Java 的类型检查不包含「这个循环一定会停」，也不包含「两个线程不会同时写同一个非 volatile 字段」。后一件事属于\"},{\"t\":\"link\",\"v\":\"求值与内存模型\",\"href\":\"../04-evaluation-memory/\"},{\"t\":\"text\",\"v\":\"和 \"},{\"t\":\"link\",\"v\":\"Java 05\",\"href\":\"../../java/05-concurrency/\"},{\"t\":\"text\",\"v\":\"。类型规则可以服务内存安全，例如拒绝把一个整数直接当成对象引用，但这不等于类型系统和内存安全是同一件事。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"转换可以把检查推迟 {#types-casts}\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"强制转换、\"},{\"t\":\"code\",\"v\":\"void *\"},{\"t\":\"text\",\"v\":\" 和未检查转换是健全性的缺口。缺口成立的条件是：翻译期不再拒绝这次使用，改由程序员保证其后的访问仍然落在定义里面。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"在 C 里，\"},{\"t\":\"code\",\"v\":\"void *\"},{\"t\":\"text\",\"v\":\" 可以携带一个对象指针，再被转换成另一种对象指针。转换本身可以是约束允许的。若随后按一个与对象有效类型不符的方式访问，就落到未定义行为那一侧。类型检查没有在转换这一步把程序挡下。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"在 Java 里，未检查转换会保留编译，并把风险推迟。参数化类型的实参在擦除之后不再作为运行期的那种参数存在。之后若按一个更具体的类型去用，失败的形式是运行期的转换错误，而不是 C 那种「定义不再给任何保证」。擦除的写法见 \"},{\"t\":\"link\",\"v\":\"Java 03\",\"href\":\"../../java/03-core-advanced/\"},{\"t\":\"text\",\"v\":\"，本页只把它当作「运行期不再保留的参数」这一个例子。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"因此「编译通过」只说明没有触发那些仍会在翻译期失败的检查。它不关闭上面这些被推迟的口子，也不证明程序没有运行错误。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"常见误读 {#types-misreadings}\",\"id\":\"h-7\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"「动态类型就是没有类型。」检查发生在运算当时，值仍然被分类。失败时语言可以规定一个明确错误。没有提前拒绝，不是没有分类。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「通过编译等于没有运行错误。」翻译期没拒绝的程序，仍可能不停机、耗尽资源，或在被推迟的转换上失败。C 还可能在那之后进入未定义行为。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「类型系统和内存安全是同一件事。」类型规则可以拒绝一部分危险使用。对象的寿命、别名和数据竞争是第 04 章的承诺。通过类型检查没有自动获得那些承诺。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"可选核对 {#types-check}\",\"id\":\"h-8\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"规则已经写在上面。这两问只核对健全性没有覆盖的边界。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"一个 Java 程序通过了类型检查。能不能据此断定它会终止？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"C 里一次经 \"},{\"t\":\"code\",\"v\":\"void *\"},{\"t\":\"text\",\"v\":\" 的转换通过了编译。这次访问是否仍被定义为合法？\"}],\"n\":2}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"不能。终止不是 Java 类型规则给出的保证。通过检查只说明程序没有被这套类型条款拒绝。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"不能。转换可以被约束允许，从而把检查推迟给程序员。按不符的类型访问对象，可以是未定义行为。编译通过没有把这个缺口补上。\"}],\"n\":2}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引 {#types-sources}\",\"id\":\"h-9\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"JLS 第 4 章 Types, Values, and Variables\",\"href\":\"https://docs.oracle.com/en/java/javase/26/docs/specs/jls/jls-4.html\"},{\"t\":\"text\",\"v\":\" — 引用类型是否相同看二元名和类型实参；4.6 定义类型擦除。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"JLS 第 5 章 Conversions and Contexts\",\"href\":\"https://docs.oracle.com/javase/specs/jls/se21/html/jls-5.html\"},{\"t\":\"text\",\"v\":\" — 转换何时是翻译期错误，何时是未检查转换。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"ISO/IEC 9899:2024\",\"href\":\"https://www.iso.org/standard/82075.html\"},{\"t\":\"text\",\"v\":\" — 约束与强制转换，包括 \"},{\"t\":\"code\",\"v\":\"void *\"},{\"t\":\"text\",\"v\":\" 与对象指针之间的转换，以及其后访问可能变成未定义行为。可读文本：\"},{\"t\":\"link\",\"v\":\"N3220\",\"href\":\"https://www.open-std.org/jtc1/sc22/wg14/www/docs/n3220.pdf\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Benjamin C. Pierce, Types and Programming Languages\",\"href\":\"https://www.cis.upenn.edu/~bcpierce/tapl/\"},{\"t\":\"text\",\"v\":\" — 健全性的概念来源：通过检查的程序不应以规则禁止的方式卡住。本页未复述证明。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"编程入门 02\",\"href\":\"../../programming-basics/02-core-concepts/\"},{\"t\":\"text\",\"v\":\" — C 的类型与转换怎么写。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Java 01\",\"href\":\"../../java/01-language-basics/\"},{\"t\":\"text\",\"v\":\" — Java 类型的用法。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Java 03 核心进阶\",\"href\":\"../../java/03-core-advanced/\"},{\"t\":\"text\",\"v\":\" — 泛型与擦除的写法。本页不重复。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Python 速成\",\"href\":\"../../ai/00-python-bridge/\"},{\"t\":\"text\",\"v\":\" — 只作动态检查的对照。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：语义\",\"href\":\"../02-semantics/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回编程\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：求值与内存模型\",\"href\":\"../04-evaluation-memory/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"这一页补哪一块 {#types-scope}\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"检查发生在翻译时，还是发生在运算时 {#types-when}\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"健全是有条件的承诺 {#types-soundness}\"},{\"id\":\"h-4\",\"level\":2,\"text\":\"比的是名字，还是形状 {#types-nominal}\"},{\"id\":\"h-5\",\"level\":2,\"text\":\"通过检查没有证明程序正确 {#types-not-correct}\"},{\"id\":\"h-6\",\"level\":2,\"text\":\"转换可以把检查推迟 {#types-casts}\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"常见误读 {#types-misreadings}\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"可选核对 {#types-check}\"},{\"id\":\"h-9\",\"level\":2,\"text\":\"资料索引 {#types-sources}\"}]},\"programming/04-evaluation-memory\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"编程\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 求值与内存模型\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这一章收束前面的区分：定义保证表达式如何变成值，也写明它在哪些程序上撤回保证。对象的共享、可见性和竞争属于语言这一层，不是页表。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"这一页补哪一块 {#memory-scope}\",\"id\":\"h-1\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"编程入门 03\",\"href\":\"../../programming-basics/03-memory-and-data/\"},{\"t\":\"text\",\"v\":\" 写 \"},{\"t\":\"code\",\"v\":\"malloc\"},{\"t\":\"text\",\"v\":\" 和结构怎么用。\"},{\"t\":\"link\",\"v\":\"编程入门 04\",\"href\":\"../../programming-basics/04-tools-debugging/\"},{\"t\":\"text\",\"v\":\" 写 ASan 和 UBSan 这些工具。\"},{\"t\":\"link\",\"v\":\"计算机组成\",\"href\":\"../../cs-basics/01-computer-organization/\"},{\"t\":\"text\",\"v\":\" 写存储层次，\"},{\"t\":\"link\",\"v\":\"操作系统\",\"href\":\"../../cs-basics/02-operating-systems/\"},{\"t\":\"text\",\"v\":\" 写进程和虚拟内存。\"},{\"t\":\"link\",\"v\":\"Java 05\",\"href\":\"../../java/05-concurrency/\"},{\"t\":\"text\",\"v\":\" 和 \"},{\"t\":\"link\",\"v\":\"Java 06\",\"href\":\"../../java/06-jvm/\"},{\"t\":\"text\",\"v\":\" 写锁、\"},{\"t\":\"code\",\"v\":\"volatile\"},{\"t\":\"text\",\"v\":\" 和 JVM 的实现。本页不重写这些。这里只保留语言允许程序员依靠的那一层约定。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"未用到的操作数可以不算，这要定义允许 {#memory-strict}\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"严格求值是：函数的实参或运算符的操作数，在运算开始前就被算出。C 的函数调用条款规定，准备调用时实参要被求值。Java 同样在进入方法体之前求值实参；多数运算符也是先求值操作数，再做运算。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这不是「实现刚好比较勤快」。惰性求值是另一种定义：未用到的实参或子表达式可以不算，而且没算仍是符合定义的。C 和 Java 以严格求值为主。它们里也有写明的例外，例如 Java 的 \"},{\"t\":\"code\",\"v\":\"&&\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"||\"},{\"t\":\"text\",\"v\":\" 和 \"},{\"t\":\"code\",\"v\":\"?:\"},{\"t\":\"text\",\"v\":\" 可以不求值未用到的那一侧。例外是条款允许的策略，不是编译器私自省略。不能从 C 和 Java 推出所有语言都严格求值。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"语言看见的对象，不是操作系统的页 {#memory-objects}\",\"id\":\"h-3\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"语言里的值、对象和引用，与操作系统的页表不是同一层。页表把虚拟地址映射到物理页。\"},{\"t\":\"link\",\"v\":\"计算机组成\",\"href\":\"../../cs-basics/01-computer-organization/\"},{\"t\":\"text\",\"v\":\" 和 \"},{\"t\":\"link\",\"v\":\"操作系统\",\"href\":\"../../cs-basics/02-operating-systems/\"},{\"t\":\"text\",\"v\":\" 讲那一层。本页只讲语言允许程序员看见的三件事：两个表达式是否可能指称同一对象（别名），这个对象是否被共享，以及它的寿命何时结束。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"实现常常把自动存储期的对象放在调用栈上，把分配得到的存储叫作堆。栈和堆在这里是寿命模型的实现说法。它们不是「操作系统的页」，也不能用页的机制代替语言对寿命的规定。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"谁撤回「这仍是一个有效对象」 {#memory-lifetime}\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"手动寿命和自动回收是两份不同的约定。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"C 有自动、静态、线程和分配这几种存储期。对象的生存期是执行中保证为它保留存储的那段时间。在生存期之外使用该对象，或在生存期结束之后再使用指向它的指针值，行为是未定义。对分配得到的存储，寿命从成功分配延续到释放。释放就是撤回「这块存储仍是一个有效对象」。本页不教 \"},{\"t\":\"code\",\"v\":\"malloc\"},{\"t\":\"text\",\"v\":\" 怎么写。谁分配、谁释放、释放之后还能不能读，见\"},{\"t\":\"link\",\"v\":\"编程入门 03\",\"href\":\"../../programming-basics/03-memory-and-data/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"Java 用可达性决定对象的存储何时可以回收。没有引用再把它当作可达对象时，回收器可以重用那块存储。程序员不是用一次显式释放来撤回保证。这并不表示对象的字段在两个线程之间自动可见，下一节单独写。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"三种「没有唯一结果」，只有一种是撤回保证 {#memory-ub}\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"已定义的行为是标准写明会发生什么。除此之外，C 的术语条款把另外三种分开，每种都有标准自己的例子：\"}]},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"分类\"}],[{\"t\":\"text\",\"v\":\"定义还留下什么\"}],[{\"t\":\"text\",\"v\":\"标准举的例子\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"实现定义\"}],[{\"t\":\"text\",\"v\":\"有多种可能，实现必须记录自己选了哪一种\"}],[{\"t\":\"text\",\"v\":\"有符号整数右移时，高位如何填充\"}]],[[{\"t\":\"text\",\"v\":\"未指定\"}],[{\"t\":\"text\",\"v\":\"有多种可能，不要求实现记录，也不要求每次相同\"}],[{\"t\":\"text\",\"v\":\"函数实参的求值顺序\"}]],[[{\"t\":\"text\",\"v\":\"未定义\"}],[{\"t\":\"text\",\"v\":\"这份定义不再提出要求\"}],[{\"t\":\"text\",\"v\":\"解引用空指针\"}]]]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"越界形成的指针若既不指向数组元素，也不指向末尾之后的那个位置，加法条款同样把它定为未定义。已经释放之后再读，是生存期条款里的未定义：对象的寿命已经结束。这两种都是撤回保证，不是「结果不稳定，但程序仍然合法」。标准允许的后果包括一直错下去，也包括在翻译或执行时终止。不能写成「一定会崩溃」。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"Java 对这类空间安全问题通常换成明确的失败或干脆不让该操作进入语言。数组下标越界时，JLS 规定抛出 \"},{\"t\":\"code\",\"v\":\"ArrayIndexOutOfBoundsException\"},{\"t\":\"text\",\"v\":\"，而不是对整个程序不再提出要求。这不等于 Java 没有并发上的数据竞争。垃圾回收撤回的是「无人可达的存储仍被你占用」，不是「两个线程的写自动排好序」。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"优化级别改变了结果时，先查程序是不是已经走到未定义行为。定义一旦不再提出要求，实现可以假定那条路径不会发生，并据此删除或改写其余代码。\"},{\"t\":\"code\",\"v\":\"-O2\"},{\"t\":\"text\",\"v\":\" 才看见的结果，可能是这个假定，而不必是编译器没有实现标准。先排除未定义行为，再谈实现缺陷。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"未定义也不是「不可计算」。不可计算说的是不存在一个对所有输入都停机并答对的算法，那是\"},{\"t\":\"link\",\"v\":\"理论基础\",\"href\":\"../../cs-theory/\"},{\"t\":\"text\",\"v\":\"里的另一件事。未定义是这份语言定义对某些程序撤回了保证。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"数据竞争和 happens-before {#memory-jmm}\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"并发的内存模型这里只到入门边界。JLS 17.4 用 happens-before 规定可见性：若动作 x happens-before 动作 y，则 x 对 y 可见，并且排在 y 之前。同一线程里的程序顺序、解锁与之后对同一管程的加锁、对 volatile 字段的写与之后的读、\"},{\"t\":\"code\",\"v\":\"start\"},{\"t\":\"text\",\"v\":\" 和 \"},{\"t\":\"code\",\"v\":\"join\"},{\"t\":\"text\",\"v\":\"，都会建立这种边。细节的锁和 \"},{\"t\":\"code\",\"v\":\"volatile\"},{\"t\":\"text\",\"v\":\" 写法不在本页，见 \"},{\"t\":\"link\",\"v\":\"Java 05\",\"href\":\"../../java/05-concurrency/\"},{\"t\":\"text\",\"v\":\" 和 \"},{\"t\":\"link\",\"v\":\"Java 06\",\"href\":\"../../java/06-jvm/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"两个冲突的访问如果没有被 happens-before 排好，这次执行就有数据竞争。JLS 写明：没有数据竞争的程序，其执行看起来是顺序一致的。顺序一致是很强的全序：每个动作原子，并且立刻对所有线程可见。这个保证的前提是没有数据竞争。不能把顺序一致写成 Java 对含有数据竞争的程序的承诺，更不能写成多数语言的默认模型。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"垃圾回收不建立 happens-before。对象仍然可达，只说明存储还没被收回，不说明另一个线程一定看得见最近一次写。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"常见误读 {#memory-misreadings}\",\"id\":\"h-7\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"「未定义行为就是结果不确定，但还能当合法程序用。」未指定才是「几种结果都合法」。未定义是定义不再提出要求，程序不能再依靠一份规定好的结果。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「栈和堆是操作系统的页，和语言定义无关。」页是操作系统的映射机制。栈对象和堆对象是语言或实现用来谈论寿命的模型。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「Java 没有内存模型问题，因为有垃圾回收。」回收只处理可达性。没有 happens-before 的冲突访问仍然是数据竞争。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「加了 \"},{\"t\":\"code\",\"v\":\"-O2\"},{\"t\":\"text\",\"v\":\" 才出现的结果，一定是编译器 bug。」也可能是未定义行为让实现撤走了「这条路径仍有定义」的假定。先查程序，再断定实现违反标准。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"可选核对 {#memory-check}\",\"id\":\"h-8\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"分类已经写在上一节。这两问只核对哪一种保证被撤回了。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"C 程序在 \"},{\"t\":\"code\",\"v\":\"free\"},{\"t\":\"text\",\"v\":\" 之后又读那块存储。标准是否保证这次读取会崩溃？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"一段 Java 程序只使用垃圾回收，两个线程写同一个普通字段，中间没有 happens-before。还有没有数据竞争？\"}],\"n\":2}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"不保证。生存期之外使用对象是未定义行为。标准不要求崩溃，也不再给一份确定结果。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"有。垃圾回收不建立 happens-before。两个冲突访问若没有这条边，按 JLS 的定义这就是数据竞争。\"}],\"n\":2}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引 {#memory-sources}\",\"id\":\"h-9\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"ISO/IEC 9899:2024\",\"href\":\"https://www.iso.org/standard/82075.html\"},{\"t\":\"text\",\"v\":\" — 术语条款区分实现定义、未定义和未指定，并给出右移、空指针和实参求值顺序三个例子。存储期条款定义生存期，并规定生存期之外的使用是未定义行为。函数调用条款规定实参在调用前求值。可读文本：\"},{\"t\":\"link\",\"v\":\"N3220\",\"href\":\"https://www.open-std.org/jtc1/sc22/wg14/www/docs/n3220.pdf\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"JLS 15.7 Evaluation Order\",\"href\":\"https://docs.oracle.com/en/java/javase/26/docs/specs/jls/jls-15.html#jls-15.7\"},{\"t\":\"text\",\"v\":\" — 严格求值，以及 \"},{\"t\":\"code\",\"v\":\"&&\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"||\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"?:\"},{\"t\":\"text\",\"v\":\" 这些允许跳过未用操作数的例外。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"JLS 17.4 Memory Model\",\"href\":\"https://docs.oracle.com/en/java/javase/26/docs/specs/jls/jls-17.html#jls-17.4\"},{\"t\":\"text\",\"v\":\" — happens-before 的定义入口。没有数据竞争时，执行看起来才是顺序一致的。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"JLS 15.10.4 数组访问的运行期求值\",\"href\":\"https://docs.oracle.com/en/java/javase/26/docs/specs/jls/jls-15.html#jls-15.10.4\"},{\"t\":\"text\",\"v\":\" — 下标越界抛出 \"},{\"t\":\"code\",\"v\":\"ArrayIndexOutOfBoundsException\"},{\"t\":\"text\",\"v\":\"，而不是撤回全部保证。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"编程入门 03\",\"href\":\"../../programming-basics/03-memory-and-data/\"},{\"t\":\"text\",\"v\":\" — 分配和释放怎么写。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"编程入门 04\",\"href\":\"../../programming-basics/04-tools-debugging/\"},{\"t\":\"text\",\"v\":\" — ASan 和 UBSan 是寻找未定义行为的工具，不是定义本身。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"计算机基础 01\",\"href\":\"../../cs-basics/01-computer-organization/\"},{\"t\":\"text\",\"v\":\" — 存储层次。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"计算机基础 02\",\"href\":\"../../cs-basics/02-operating-systems/\"},{\"t\":\"text\",\"v\":\" — 进程和虚拟内存。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Java 05 并发\",\"href\":\"../../java/05-concurrency/\"},{\"t\":\"text\",\"v\":\" — 锁和 \"},{\"t\":\"code\",\"v\":\"volatile\"},{\"t\":\"text\",\"v\":\"。本页不重写。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Java 06 JVM\",\"href\":\"../../java/06-jvm/\"},{\"t\":\"text\",\"v\":\" — JVM 如何实现这些条款。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：类型系统\",\"href\":\"../03-types/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回编程\",\"href\":\"../\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"这一页补哪一块 {#memory-scope}\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"未用到的操作数可以不算，这要定义允许 {#memory-strict}\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"语言看见的对象，不是操作系统的页 {#memory-objects}\"},{\"id\":\"h-4\",\"level\":2,\"text\":\"谁撤回「这仍是一个有效对象」 {#memory-lifetime}\"},{\"id\":\"h-5\",\"level\":2,\"text\":\"三种「没有唯一结果」，只有一种是撤回保证 {#memory-ub}\"},{\"id\":\"h-6\",\"level\":2,\"text\":\"数据竞争和 happens-before {#memory-jmm}\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"常见误读 {#memory-misreadings}\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"可选核对 {#memory-check}\"},{\"id\":\"h-9\",\"level\":2,\"text\":\"资料索引 {#memory-sources}\"}]},\"web/origin\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"Web\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 浏览器里的源\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"浏览器把文档和脚本按源隔开。源由方案、主机和端口组成，不是「看起来像同一个网站」。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"这一页补哪一块\",\"id\":\"h-1\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"计算机网络\",\"href\":\"../../cs-basics/05-networking/\"},{\"t\":\"text\",\"v\":\" 已经写了 HTTP 的请求行、状态码，以及 TLS 保护传输、并用证书核对域名。那一章没有写：页面里的脚本能不能读到另一个地址的文档或响应正文。本页只写浏览器的这个边界。它不教 HTML 标签，也不教后端框架。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"界面如何挂上文档、请求如何变成响应、以及跨源时框架能声明什么，写在本主题的\"},{\"t\":\"link\",\"v\":\"界面与渲染模型\",\"href\":\"../02-rendering/\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"link\",\"v\":\"请求处理与中间件\",\"href\":\"../03-request-handling/\"},{\"t\":\"text\",\"v\":\"和\"},{\"t\":\"link\",\"v\":\"跨越源边界\",\"href\":\"../04-crossing-boundary/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"源是三元组\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"HTML 现行标准把源当作 Web 平台的权限单位。一个元组源包含方案、主机和端口。两个元组源相同，当且仅当方案相同、主机相同、端口相同。路径不参与比较。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"以 \"},{\"t\":\"code\",\"v\":\"https://shop.example/cart\"},{\"t\":\"text\",\"v\":\" 为基准，默认端口是 443：\"}]},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"URL\"}],[{\"t\":\"text\",\"v\":\"是否同源\"}],[{\"t\":\"text\",\"v\":\"原因\"}]],\"rows\":[[[{\"t\":\"code\",\"v\":\"https://shop.example/api/orders\"}],[{\"t\":\"text\",\"v\":\"是\"}],[{\"t\":\"text\",\"v\":\"只多了路径\"}]],[[{\"t\":\"code\",\"v\":\"http://shop.example/cart\"}],[{\"t\":\"text\",\"v\":\"否\"}],[{\"t\":\"text\",\"v\":\"方案从 https 变成 http\"}]],[[{\"t\":\"code\",\"v\":\"https://shop.example:8443/cart\"}],[{\"t\":\"text\",\"v\":\"否\"}],[{\"t\":\"text\",\"v\":\"端口不是 443\"}]],[[{\"t\":\"code\",\"v\":\"https://api.shop.example/cart\"}],[{\"t\":\"text\",\"v\":\"否\"}],[{\"t\":\"text\",\"v\":\"主机不同\"}]]]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这张表是在套定义，不是在某一种浏览器里点出来的实验结果。\"},{\"t\":\"code\",\"v\":\"file:\"},{\"t\":\"text\",\"v\":\" 的源由实现决定，标准并不保证同一目录下的两个本地文件同源。本页的结论限于有方案、主机和端口的网络源。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"同源策略限制什么\",\"id\":\"h-3\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"同源策略限制一个源里的文档或脚本如何接触另一个源的资源。MDN 把典型风险写成：恶意页面里的脚本不应读到用户已登录的第三方邮箱，或只在内网才能打开的页面。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"脚本直接拿另一个窗口的文档时，不同源只能做很窄的一组操作，例如 \"},{\"t\":\"code\",\"v\":\"postMessage\"},{\"t\":\"text\",\"v\":\"。读对方的 DOM、或把 \"},{\"t\":\"code\",\"v\":\"fetch\"},{\"t\":\"text\",\"v\":\" 的响应正文交给脚本，默认不行。存储也按源分开：一个源的脚本不能读写另一个源的 Web Storage 或 IndexedDB。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"跨源的写和嵌入常常被允许。链接、表单提交属于写。用 \"},{\"t\":\"code\",\"v\":\"img\"},{\"t\":\"text\",\"v\":\" 或 \"},{\"t\":\"code\",\"v\":\"script\"},{\"t\":\"text\",\"v\":\" 嵌进页面，会漏出一些信息，例如图片尺寸或脚本有没有加载成功，但不是把响应正文交给你的脚本。所以「请求发出去了」不等于「脚本读到了正文」。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"和 TLS、Cookie 不是同一层\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"证书证明传输对端持有该域名的私钥。\"},{\"t\":\"link\",\"v\":\"计算机网络\",\"href\":\"../../cs-basics/05-networking/\"},{\"t\":\"text\",\"v\":\" 写过：合法证书不证明网站内容可信。它同样不证明另一个源的脚本可以读你的页面。\"},{\"t\":\"code\",\"v\":\"https://evil.example\"},{\"t\":\"text\",\"v\":\" 可以有自己的合法证书，它和 \"},{\"t\":\"code\",\"v\":\"https://shop.example\"},{\"t\":\"text\",\"v\":\" 仍然不同源。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"Cookie 用另一套范围。页面可以为自己的域或父域设置 Cookie，父域不能是公共后缀；读取时看不出这条 Cookie 当初是从哪个源写下的。因此「带上 Cookie」不是「两个 URL 同源」。HTTP 无状态说的是协议本身不记住上一次请求，登录状态要靠 Cookie 或令牌再带上。无状态并不取消浏览器对脚本的源隔离。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"CORS 是服务器的放行，不是把边界删掉\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"跨源读取默认不交给脚本。CORS 是 HTTP 的一组响应头，用来声明浏览器可以把这次跨源响应暴露给哪个源的脚本。服务器没有给出允许时，浏览器可以已经发出了请求，但仍不把正文交给脚本。把 CORS 说成「关闭同源策略」会漏掉这一步：放行的是某一次读取，边界还在。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"常见误读\",\"id\":\"h-6\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"「路径不同就不同源」。\"},{\"t\":\"code\",\"v\":\"/cart\"},{\"t\":\"text\",\"v\":\" 和 \"},{\"t\":\"code\",\"v\":\"/api/orders\"},{\"t\":\"text\",\"v\":\" 在方案、主机、端口相同时同源。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「用了 HTTPS 就可以互相读页面」。TLS 保护传输并核对域名，不合并源。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「请求返回 200，脚本就拿到了 JSON」。跨源时，状态码属于响应；脚本能否读取正文还要看同源或 CORS。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「Cookie 的域和源是同一个三元组」。Cookie 的域可以是父域，而且读的时候不显示写入时的源。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"可选核对\",\"id\":\"h-7\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"定义在上一节已经写完。这两问只核对边界。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"code\",\"v\":\"https://shop.example/cart\"},{\"t\":\"text\",\"v\":\" 里的脚本，默认为什么读不到 \"},{\"t\":\"code\",\"v\":\"https://api.shop.example/cart\"},{\"t\":\"text\",\"v\":\" 的响应正文？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"两个 URL 只差路径。它们同源吗？这是否表示 TLS 已经保证页面内容可信？\"}],\"n\":2}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"主机不同，所以不同源。默认同源策略不把另一个源的响应正文交给脚本。对方即使返回 200，也改变不了源的比较。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"同源，因为方案、主机、端口相同。TLS 只保护传输并核对域名，不证明页面内容可信，这是网络章已经分开的两件事。\"}],\"n\":2}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引\",\"id\":\"h-8\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"HTML Living Standard：Origin\",\"href\":\"https://html.spec.whatwg.org/multipage/origin.html#origin\"},{\"t\":\"text\",\"v\":\" — 源是方案、主机、端口和域组成的元组；相同性比较方案、主机和端口。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"MDN：Same-origin policy\",\"href\":\"https://developer.mozilla.org/en-US/docs/Web/Security/Defenses/Same-origin_policy\"},{\"t\":\"text\",\"v\":\" — 脚本与文档的跨源隔离、默认可做的写和嵌入，以及 Cookie 使用另一套范围。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"计算机网络：HTTP 与 HTTPS\",\"href\":\"../../cs-basics/05-networking/\"},{\"t\":\"text\",\"v\":\" — 报文格式和 TLS，不替代本页的源。\"}]}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"这一页补哪一块\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"源是三元组\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"同源策略限制什么\"},{\"id\":\"h-4\",\"level\":2,\"text\":\"和 TLS、Cookie 不是同一层\"},{\"id\":\"h-5\",\"level\":2,\"text\":\"CORS 是服务器的放行，不是把边界删掉\"},{\"id\":\"h-6\",\"level\":2,\"text\":\"常见误读\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"可选核对\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"资料索引\"}]},\"web/02-rendering\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"Web\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 界面与渲染模型\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"前端框架约定的是：界面如何从状态推导出来，以及这次推导在什么时候发生。它不取消文档，也不取消源。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"这一页补哪一块 {#rendering-scope}\",\"id\":\"h-1\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"浏览器里的源\",\"href\":\"../origin/\"},{\"t\":\"text\",\"v\":\" 写方案、主机和端口，以及脚本默认可读的范围。本页不重讲三元组，也不教 HTML 标签或 CSS。框架名只用来说明「状态推导出界面」这一条约定，不是一份库的教程，更不是 Web 平台本身。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"文档在下，推导在上 {#rendering-document}\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"浏览器先有文档和文档树。HTML 把文档当作树状的节点结构，页面上的元素是这棵树的一部分。浏览上下文负责展示其中一个文档。这是平台已经有的东西。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"前端框架通常再约定一层：用当前状态算出应当显示的视图。它保证的是推导关系和更新边界：同样的状态应当得到同样的视图描述，状态变了才需要把文档改到和新描述一致。它不保证某一次虚拟 DOM 或 diff 算法的内部步骤。那些步骤是某个库把「描述」落到文档上的办法，换一个库可以换一套步骤，推导关系仍可以是同一条。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"所以「用了前端框架」推不出「文档和源消失了」。框架产出的仍是要放进文档的结果。脚本能不能读另一个源的文档，仍由源决定。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"数据没到，还是视图算错了 {#rendering-timing}\",\"id\":\"h-3\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"渲染时机要分开看。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"首次绘制：用当时已有的状态算出第一份视图。状态里可以还没有服务器的数据。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"状态变更之后：只重新推导受这次变更影响的那一部分，再把文档改到一致。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"和网络往返的关系：请求发出去，视图不会因此自动变成「数据已到」。返回之后，要有人把结果写进状态，推导才会变。\"}],\"n\":3}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"「数据还没到」是异步和边界问题。界面可以诚实地显示等待，这不表示推导算错了。「视图算错了」才是渲染约定没守住：状态里已经有购物车的三件商品，画面却仍按零件在画。请求是否已经到达，见 \"},{\"t\":\"link\",\"v\":\"计算机网络\",\"href\":\"../../cs-basics/05-networking/\"},{\"t\":\"text\",\"v\":\"。那一章的报文不等于本页的视图已经更新。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"改路径不是换源 {#rendering-route}\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"客户端路由改的是地址栏里的路径，以及当前要显示的视图。整页导航会换掉文档，由服务器或下一次加载给出新文档。两条路都没有因为路径变了就换一个源。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"源的比较不看路径。\"},{\"t\":\"link\",\"v\":\"浏览器里的源\",\"href\":\"../origin/\"},{\"t\":\"text\",\"v\":\" 已经写过：\"},{\"t\":\"code\",\"v\":\"/cart\"},{\"t\":\"text\",\"v\":\" 和 \"},{\"t\":\"code\",\"v\":\"/api/orders\"},{\"t\":\"text\",\"v\":\" 在方案、主机、端口相同时仍是同一个源。本页不重讲这个三元组。路由库把路径映射到哪个视图，是应用约定，不是浏览器对源的定义。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"画得出来，不等于跨源可读 {#rendering-limits}\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"框架不保证这三件事。脚本默认可不可以读另一个源的响应，由源和 CORS 决定，不由组件画出来决定。Cookie 出现在请求里，也不自动变成「已经登录且安全」。后端资源是否正确，是请求处理和业务的事，不在「状态能算出一棵树」里。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"跨源读取放在 \"},{\"t\":\"link\",\"v\":\"跨越源边界\",\"href\":\"../04-crossing-boundary/\"},{\"t\":\"text\",\"v\":\"。请求如何变成响应，放在 \"},{\"t\":\"link\",\"v\":\"请求处理与中间件\",\"href\":\"../03-request-handling/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"同一份购物车状态，两种约定各管一段：\"}]},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"做法\"}],[{\"t\":\"text\",\"v\":\"这一侧约定了什么\"}],[{\"t\":\"text\",\"v\":\"留给网络的是什么\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"整页刷新，服务器生成 HTML\"}],[{\"t\":\"text\",\"v\":\"服务器用当时的状态生成文档；浏览器展示这份文档\"}],[{\"t\":\"text\",\"v\":\"每一次查看都是一次新的文档请求。客户端不另持一份要推导的状态\"}]],[[{\"t\":\"text\",\"v\":\"客户端持有状态再推导 DOM\"}],[{\"t\":\"text\",\"v\":\"状态变了就重新推导视图，再改文档\"}],[{\"t\":\"text\",\"v\":\"状态从哪一次响应写入，仍是请求的事。画得出来只说明本地推导跑过\"}]]]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"第二种没有取消源，也没有把「请求已返回」写成「视图已经对」。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"常见误读 {#rendering-misreadings}\",\"id\":\"h-6\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"「用了前端框架，就不存在文档和源了。」框架多了一层推导。文档仍是浏览器里的树，源仍按方案、主机和端口划分。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「路由变了就是换了一个网站（换源）。」路径不参加源的比较。换视图不等于换源。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「虚拟 DOM 或某库的 diff 等于渲染模型的定义。」diff 是某个库把新描述落到文档上的步骤。定义是「视图由状态推导」，不是那套步骤的名字。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「界面能画出来，就说明跨源 API 已经可读。」画面可以来自本地状态或同源文档。另一个源的响应正文默认可不可以交给脚本，是源的规则。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"可选核对 {#rendering-check}\",\"id\":\"h-7\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"推导和源已经分开写了。这两问只核对哪一条没被框架取消。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"客户端路由从 \"},{\"t\":\"code\",\"v\":\"/cart\"},{\"t\":\"text\",\"v\":\" 变到 \"},{\"t\":\"code\",\"v\":\"/orders\"},{\"t\":\"text\",\"v\":\"，主机没变。源变了吗？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"购物车组件已经画出三件商品，但这些数字只写在组件的初始状态里，列表请求还没返回。这能说明跨源接口的正文已经交给脚本了吗？\"}],\"n\":2}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"没有。源比较方案、主机和端口。路径变化只改要显示的视图，或触发一次导航。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"不能。画出来只说明本地状态被推导过。跨源正文是否可读，仍看源和 CORS，不看组件是否出现。\"}],\"n\":2}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引 {#rendering-sources}\",\"id\":\"h-8\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"HTML Living Standard：Document\",\"href\":\"https://html.spec.whatwg.org/multipage/dom.html#document\"},{\"t\":\"text\",\"v\":\" — 文档是节点树。本页只取「浏览器先有文档」，不抄规范长文。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"React：Render and Commit\",\"href\":\"https://react.dev/learn/render-and-commit\"},{\"t\":\"text\",\"v\":\" — 概念来源：用当前输入调用组件得到界面描述，再把文档改到与这份描述一致。本页不是该库教程，也不把 diff 写成 Web 平台的定义。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"浏览器里的源\",\"href\":\"../origin/\"},{\"t\":\"text\",\"v\":\" — 路径不改变源。本页不重讲三元组。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"计算机网络\",\"href\":\"../../cs-basics/05-networking/\"},{\"t\":\"text\",\"v\":\" — 请求已经发出，不等于本页的视图已经更新。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"返回 Web\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：请求处理与中间件\",\"href\":\"../03-request-handling/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"这一页补哪一块 {#rendering-scope}\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"文档在下，推导在上 {#rendering-document}\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"数据没到，还是视图算错了 {#rendering-timing}\"},{\"id\":\"h-4\",\"level\":2,\"text\":\"改路径不是换源 {#rendering-route}\"},{\"id\":\"h-5\",\"level\":2,\"text\":\"画得出来，不等于跨源可读 {#rendering-limits}\"},{\"id\":\"h-6\",\"level\":2,\"text\":\"常见误读 {#rendering-misreadings}\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"可选核对 {#rendering-check}\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"资料索引 {#rendering-sources}\"}]},\"web/03-request-handling\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"Web\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 请求处理与中间件\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"后端框架约定的是：一次已经到达应用的请求，如何按映射和顺序变成响应。映射本身不是 HTTP，跑通也不等于业务正确。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"这一页补哪一块 {#request-scope}\",\"id\":\"h-1\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"计算机网络\",\"href\":\"../../cs-basics/05-networking/\"},{\"t\":\"text\",\"v\":\" 写报文和状态码。本页不重讲那一章。状态码的含义仍以 HTTP 为准，不随某个框架的路由表改变。\"},{\"t\":\"link\",\"v\":\"Spring\",\"href\":\"../../java/09-spring/\"},{\"t\":\"text\",\"v\":\" 写 MVC 和 WebFlux 怎么实现。本页不写注解清单，也不教数据库访问。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"API 网关\",\"href\":\"../../microservices/02-api-gateway/\"},{\"t\":\"text\",\"v\":\" 是多服务前面的入口。\"},{\"t\":\"link\",\"v\":\"服务通信\",\"href\":\"../../microservices/04-communication/\"},{\"t\":\"text\",\"v\":\" 是服务之间的客户端。两者都不是「一个应用进程里，请求从进来到出去」的那条管道。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"映射只说明谁被调用 {#request-route}\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"资源在这里是应用承认的一对：哪个 URL、哪种方法，交给哪一段逻辑。框架保证的是这张映射，以及它调用这段逻辑的时机。它不保证订单真的该被创建，也不保证金额算对了。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"路由表是应用的约定，不是 HTTP 的一部分。协议规定请求行长什么样、状态码表示什么。框架规定「这条请求行进来之后，调用哪一个处理函数」。没有这张表，HTTP 仍然是 HTTP；有了这张表，也不表示协议多了一条方法。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"链的顺序是约定的一部分 {#request-chain}\",\"id\":\"h-3\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"中间件或过滤器是插在「进来」和「出去」之间的步骤：解析体、鉴权、记日志、把错误收成统一的响应。经典的过滤器模型是一条链：每一环决定把请求继续交下去，还是就地结束。容器或框架按声明的顺序调用它们。这个顺序是模型的一部分，不是某个框架版本的私货。本页不绑定某一版 Servlet 或 Spring。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"顺序敏感，因为每一环看见的请求不一样。\"}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"先解析再鉴权：未通过身份的请求也会把体读进来。解析本身可能很贵，也可能在鉴权之前就按体里的内容做了动作。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"先鉴权再碰体：没通过的请求不会进入解析和处理。鉴权看不见体里的字段，除非它自己再读一次。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"两种都可以是合法约定。不能从「能跑通」推出顺序无所谓。调换之后，被保护的命题就换了。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"网关不是这条链的同义词 {#request-gateway}\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"反向代理和 API 网关站在多个服务前面，做入口路由、鉴权和限流。那是另一条边界，见 \"},{\"t\":\"link\",\"v\":\"API 网关\",\"href\":\"../../microservices/02-api-gateway/\"},{\"t\":\"text\",\"v\":\"。本页只讨论单个应用进程内的管道。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"有网关，应用里的管道还在。网关放行之后，请求仍要在应用里被映射、被链上的步骤处理。把网关过滤器写成应用中间件的同义词，会让人以为入口策略已经代替了应用自己的鉴权和解析。服务间的客户端调用也不是这条管道，见 \"},{\"t\":\"link\",\"v\":\"服务通信\",\"href\":\"../../microservices/04-communication/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"异步没有取消超时 {#request-async}\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"同步处理时，一个线程从进入处理函数等到响应写完。异步或非阻塞模型改的是谁在何时占用线程：等待外部结果时可以先让出线程。它不改「这一次请求有没有在截止时间前得到响应」。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"超时仍然是这条管道上的事实。客户端或代理可以先放弃，应用稍后才写完。非阻塞只改变等待时占不占着线程，不保证响应一定来得及。实现上 MVC 和 WebFlux 的差别见 \"},{\"t\":\"link\",\"v\":\"Spring\",\"href\":\"../../java/09-spring/\"},{\"t\":\"text\",\"v\":\"，本页不把其中一种写成 Web 平台的默认。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"一次 POST 的四步 {#request-derivation}\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"约定写成「解析 → 鉴权 → 处理 → 写响应」时，一次 \"},{\"t\":\"code\",\"v\":\"POST /orders\"},{\"t\":\"text\",\"v\":\" 是：\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"解析：体被读成订单草稿。还没有创建订单。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"鉴权：确认调用者可以创建订单。没通过就停止，草稿不进入处理。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"处理：按草稿创建订单。业务对不对，是这一步的事，不是路由表的事。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"写响应：把处理结果变成状态码和正文。状态码的含义仍按 HTTP，不按框架的函数名。\"}],\"n\":4}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"抽掉鉴权：未确认身份的请求也会创建订单。被破坏的是「只有通过身份的调用者才能进入处理」。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"把写响应提前到处理之前：客户端收到的是还没创建订单的结果。被破坏的是「响应描述的是处理之后的状态」。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"两条都可能仍然返回 200。200 只说明 HTTP 语义里的成功，不说明上面那份应用约定还在。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"常见误读 {#request-misreadings}\",\"id\":\"h-7\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"「框架路由就是 HTTP 协议的一部分。」路由是应用把请求行映射到处理函数。协议不因为多了一张路由表而改变。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「有网关了，应用里就不用谈请求管道。」网关是多服务入口。请求进入某一个应用之后，映射和中间步骤仍是那个进程里的约定。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「中间件顺序无所谓，能跑通就行。」先解析还是先鉴权，决定未授权的请求会不会碰体、会不会进入处理。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「用了 WebFlux 或异步，超时就不会发生。」异步改变的是等待时占不占线程。截止时间仍然可以先到。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"可选核对 {#request-check}\",\"id\":\"h-8\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"管道和协议已经分开。这两问只核对约定还在不在。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"应用把 \"},{\"t\":\"code\",\"v\":\"POST /orders\"},{\"t\":\"text\",\"v\":\" 映射到一个函数，并返回 201。这是否说明 HTTP 新增了一种「创建订单」方法？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"链从「鉴权 → 解析 → 处理」改成「解析 → 处理」，鉴权被拿掉，测试仍返回 200。约定有没有变？\"}],\"n\":2}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"没有。201 仍是 HTTP 的状态码。映射只说明这个应用用哪个函数处理这对 URL 和方法。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"变了。未通过身份的请求现在也会进入处理。能返回 200 只说明响应写出去了，不说明「先鉴权」还在。\"}],\"n\":2}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引 {#request-sources}\",\"id\":\"h-9\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"RFC 9110：HTTP Semantics\",\"href\":\"https://www.rfc-editor.org/rfc/rfc9110\"},{\"t\":\"text\",\"v\":\" — 方法和状态码属于协议。本页的路由和中间件不是这套语义的一部分。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Jakarta Servlet 规范：Filtering\",\"href\":\"https://jakarta.ee/specifications/servlet/6.1/jakarta-servlet-spec-6.1.html#filtering\"},{\"t\":\"text\",\"v\":\" — 模型来源：过滤器组成链，容器按配置顺序调用，每一环可以选择继续或结束。本页不绑定该规范的某一实现版本，也不把它写成唯一的 Web 框架。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"计算机网络\",\"href\":\"../../cs-basics/05-networking/\"},{\"t\":\"text\",\"v\":\" — 报文和状态码。本页不重讲。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Spring 框架\",\"href\":\"../../java/09-spring/\"},{\"t\":\"text\",\"v\":\" — MVC 与 WebFlux 的实现。超时和线程模型的细节在那里。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"API 网关\",\"href\":\"../../microservices/02-api-gateway/\"},{\"t\":\"text\",\"v\":\" — 多服务入口，不是应用进程内的管道。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"服务通信\",\"href\":\"../../microservices/04-communication/\"},{\"t\":\"text\",\"v\":\" — 服务间客户端，不是浏览器进入应用的同一条链。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：界面与渲染模型\",\"href\":\"../02-rendering/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回 Web\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：跨越源边界\",\"href\":\"../04-crossing-boundary/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"这一页补哪一块 {#request-scope}\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"映射只说明谁被调用 {#request-route}\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"链的顺序是约定的一部分 {#request-chain}\"},{\"id\":\"h-4\",\"level\":2,\"text\":\"网关不是这条链的同义词 {#request-gateway}\"},{\"id\":\"h-5\",\"level\":2,\"text\":\"异步没有取消超时 {#request-async}\"},{\"id\":\"h-6\",\"level\":2,\"text\":\"一次 POST 的四步 {#request-derivation}\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"常见误读 {#request-misreadings}\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"可选核对 {#request-check}\"},{\"id\":\"h-9\",\"level\":2,\"text\":\"资料索引 {#request-sources}\"}]},\"web/04-crossing-boundary\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"Web\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 跨越源边界\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"渲染和请求处理接到一起时，框架只能声明自己踩在源的哪一层。它不能把浏览器的边界删掉。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"这一页补哪一块 {#boundary-scope}\",\"id\":\"h-1\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"浏览器里的源\",\"href\":\"../origin/\"},{\"t\":\"text\",\"v\":\" 已经定义三元组、默认可读的范围，以及 CORS 是按次放行。本页不重抄那些定义。这里只把框架里常见的动作对到那几层上：封装过的 \"},{\"t\":\"code\",\"v\":\"fetch\"},{\"t\":\"text\",\"v\":\"、表单提交、Cookie，以及服务器先写出的 HTML。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"界面与渲染模型\",\"href\":\"../02-rendering/\"},{\"t\":\"text\",\"v\":\" 管状态如何变成视图。\"},{\"t\":\"link\",\"v\":\"请求处理与中间件\",\"href\":\"../03-request-handling/\"},{\"t\":\"text\",\"v\":\" 管已经到达应用的请求如何变成响应。认证协议怎么落地，见 \"},{\"t\":\"link\",\"v\":\"安全\",\"href\":\"../../microservices/11-security/\"},{\"t\":\"text\",\"v\":\"。本页只保留和源、CORS 交叉的那几条，不写成 OAuth 教程。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"框架动作踩在哪一层 {#boundary-actions}\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"脚本默认可读的范围由源决定。CORS 是服务器声明「这一次可以把响应交给哪个源的脚本」。框架配置 CORS，仍然是在做这一次放行，不是把同源策略关掉。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"表单提交通常是一次导航式的写：浏览器带着表单去请求，响应用来替换文档。提交页面里的脚本并没有因此拿到响应正文。\"},{\"t\":\"code\",\"v\":\"fetch\"},{\"t\":\"text\",\"v\":\" 才把响应对象交给发起它的脚本；跨源时，能不能读正文仍看 CORS。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"框架若把两种都叫「提交」，就要写清有没有把跨源正文交给脚本。只是导航，源的读限制没有被打开。封装成 \"},{\"t\":\"code\",\"v\":\"fetch\"},{\"t\":\"text\",\"v\":\" 却没有 CORS 允许，脚本仍然读不到正文。封装改变不了这条默认。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"带上 Cookie 不是变成同源 {#boundary-cookie}\",\"id\":\"h-3\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"Cookie 用域和路径，另加 \"},{\"t\":\"code\",\"v\":\"SameSite\"},{\"t\":\"text\",\"v\":\" 决定跨站时带不带。Fetch 把凭证模式分成不带、仅同源、以及包含凭证。带上凭证的跨源请求，仍然是跨源：脚本能不能读响应，还要服务器明确允许，并且允许时不能再用通配来源去搭配凭证。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"所以「框架默认带 Cookie」只说明请求可能附上了凭证。它不说明两个 URL 同源，也不说明登录因此是安全的。源和 Cookie 不是同一个三元组，origin 章已经分开。认证协议本身见 \"},{\"t\":\"link\",\"v\":\"安全\",\"href\":\"../../microservices/11-security/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"第一份 HTML 从哪来 {#boundary-ssr}\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"服务端渲染改变的是第一份 HTML 从哪来：服务器先写出文档，浏览器再在这份文档上恢复事件和状态。这个恢复常被叫作水合。它是「状态在哪接上」的约定，不是源的合并。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"服务器持有的证书仍只证明传输对端，不证明页面可以读另一个源。水合发生在已经载入的这份文档里。文档的源没有因为 HTML 来自服务器就扩大。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"同域转发没有取消上游 {#boundary-bff}\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"BFF 或同域反向代理让浏览器只请求自己的源，再由己方服务器去访问上游。浏览器到 BFF 仍是一个源：脚本读到的是这个源的响应。BFF 到上游是服务器发出的调用，不受浏览器同源策略的同一套限制，信任落在 BFF 上。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这不是「没有跨源问题了」。上游是谁、BFF 愿意代它做什么，变成了 BFF 的责任。入口上的网关和这里的差别见 \"},{\"t\":\"link\",\"v\":\"API 网关\",\"href\":\"../../microservices/02-api-gateway/\"},{\"t\":\"text\",\"v\":\"：网关常站在多个服务前面；BFF 在这里特指浏览器只看见己方源、由己方再去访问上游。两条都没有改写浏览器里的源。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"页面在 \"},{\"t\":\"code\",\"v\":\"https://shop.example\"},{\"t\":\"text\",\"v\":\"，API 在 \"},{\"t\":\"code\",\"v\":\"https://api.shop.example\"},{\"t\":\"text\",\"v\":\"：\"}]},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"走法\"}],[{\"t\":\"text\",\"v\":\"脚本可读性\"}],[{\"t\":\"text\",\"v\":\"Cookie\"}],[{\"t\":\"text\",\"v\":\"信任落在哪\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"浏览器直连 API，靠 CORS\"}],[{\"t\":\"text\",\"v\":\"主机不同，默认读不到正文。只有该次响应允许时，脚本才读得到\"}],[{\"t\":\"text\",\"v\":\"跨站是否附上，看 \"},{\"t\":\"code\",\"v\":\"SameSite\"},{\"t\":\"text\",\"v\":\" 和凭证模式。附上也不变成同源\"}],[{\"t\":\"text\",\"v\":\"浏览器执行源和 CORS；API 自己决定放不放行\"}]],[[{\"t\":\"text\",\"v\":\"同域 BFF 转发\"}],[{\"t\":\"text\",\"v\":\"脚本读的是 \"},{\"t\":\"code\",\"v\":\"shop.example\"},{\"t\":\"text\",\"v\":\" 的响应，这次读取是同源的\"}],[{\"t\":\"text\",\"v\":\"可以是 \"},{\"t\":\"code\",\"v\":\"shop.example\"},{\"t\":\"text\",\"v\":\" 的第一方 Cookie。上游看不到浏览器的那张源比较\"}],[{\"t\":\"text\",\"v\":\"浏览器只信任到 BFF。BFF 再决定如何调用上游\"}]]]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"第二种没有让 \"},{\"t\":\"code\",\"v\":\"api.shop.example\"},{\"t\":\"text\",\"v\":\" 变成页面的源。它只是让脚本不必直接读那个源。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"常见误读 {#boundary-misreadings}\",\"id\":\"h-6\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"「开了 CORS，同源策略就关闭了。」框架里的 CORS 配置仍是按次放行。没被允许的读取，正文还是不交给脚本。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「SSR 之后就没有源的问题了。」服务器写出第一份 HTML，只改变第一字节从哪来、状态在哪恢复。文档的源还在，证书也不变成读另一个源的许可。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「同域代理了，上游是谁都无所谓。」浏览器不再直接读上游，信任改落在代理上。上游仍是代理要去调用的另一边。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「框架默认带 Cookie，所以已经安全登录。」带上凭证不是同源，也不是一次完整的认证协议。它只影响这张请求附不附 Cookie。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"可选核对 {#boundary-check}\",\"id\":\"h-7\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"两层调用已经分开。这两问只核对边界还在不在。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"页面把跨源 \"},{\"t\":\"code\",\"v\":\"fetch\"},{\"t\":\"text\",\"v\":\" 的 CORS 开关打开了。同源策略是否因此关闭？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"浏览器只请求 \"},{\"t\":\"code\",\"v\":\"https://shop.example\"},{\"t\":\"text\",\"v\":\"，由它的服务器再调用 \"},{\"t\":\"code\",\"v\":\"https://api.shop.example\"},{\"t\":\"text\",\"v\":\"。脚本读到的响应是哪个源的？上游还有没有自己的信任边界？\"}],\"n\":2}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"没有。CORS 放行的是某一次读取。其他源、其他响应，默认仍然不把正文交给脚本。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"脚本读到的是 \"},{\"t\":\"code\",\"v\":\"shop.example\"},{\"t\":\"text\",\"v\":\" 的同源响应。上游仍要由这台服务器决定怎么调用、信任到哪。同域代理没有把上游并进页面的源。\"}],\"n\":2}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引 {#boundary-sources}\",\"id\":\"h-8\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"HTML Living Standard：Origin\",\"href\":\"https://html.spec.whatwg.org/multipage/origin.html#origin\"},{\"t\":\"text\",\"v\":\" — 源的定义。本页不重抄，只把框架动作映射到这一定义上。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"MDN：Same-origin policy\",\"href\":\"https://developer.mozilla.org/en-US/docs/Web/Security/Defenses/Same-origin_policy\"},{\"t\":\"text\",\"v\":\" — 默认可读范围、表单和嵌入属于哪一类。origin 章已引，这里用来对上「导航式的写」和「交给脚本的读」。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Fetch：credentials mode\",\"href\":\"https://fetch.spec.whatwg.org/#concept-request-credentials-mode\"},{\"t\":\"text\",\"v\":\" — 请求可以不带凭证、只在同源时带，或明确包含凭证。包含凭证并不改变源的比较。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"MDN：Set-Cookie / SameSite\",\"href\":\"https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Set-Cookie#samesite\"},{\"t\":\"text\",\"v\":\" — 跨站时 Cookie 带不带，是 Cookie 的规则，不是源的三元组。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"React：hydrateRoot\",\"href\":\"https://react.dev/reference/react-dom/client/hydrateRoot\"},{\"t\":\"text\",\"v\":\" — 概念来源：在服务器已经生成的 HTML 上恢复客户端组件。本页不是该库教程，也不把水合写成取消源。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"浏览器里的源\",\"href\":\"../origin/\"},{\"t\":\"text\",\"v\":\" — 三元组、CORS 和 Cookie 的分界。本页必读的前提。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"界面与渲染模型\",\"href\":\"../02-rendering/\"},{\"t\":\"text\",\"v\":\" — 状态如何变成视图。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"请求处理与中间件\",\"href\":\"../03-request-handling/\"},{\"t\":\"text\",\"v\":\" — 请求到达应用之后如何变成响应。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"计算机网络\",\"href\":\"../../cs-basics/05-networking/\"},{\"t\":\"text\",\"v\":\" — 报文和 TLS。证书不扩大源。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"API 网关\",\"href\":\"../../microservices/02-api-gateway/\"},{\"t\":\"text\",\"v\":\" — 入口和这里的同域转发不是同一条边界。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"安全\",\"href\":\"../../microservices/11-security/\"},{\"t\":\"text\",\"v\":\" — OAuth2 / OIDC 的落地。本页只保留与源交叉的那几条。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：请求处理与中间件\",\"href\":\"../03-request-handling/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回 Web\",\"href\":\"../\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"这一页补哪一块 {#boundary-scope}\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"框架动作踩在哪一层 {#boundary-actions}\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"带上 Cookie 不是变成同源 {#boundary-cookie}\"},{\"id\":\"h-4\",\"level\":2,\"text\":\"第一份 HTML 从哪来 {#boundary-ssr}\"},{\"id\":\"h-5\",\"level\":2,\"text\":\"同域转发没有取消上游 {#boundary-bff}\"},{\"id\":\"h-6\",\"level\":2,\"text\":\"常见误读 {#boundary-misreadings}\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"可选核对 {#boundary-check}\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"资料索引 {#boundary-sources}\"}]},\"systems/distributed\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"系统\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 分布式系统模型\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这里的「分布式」指多台会独立失效的计算体只能靠消息协作。它不重写进程、TCP 或 SQL。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"这一页补哪一块\",\"id\":\"h-1\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"操作系统\",\"href\":\"../../cs-basics/02-operating-systems/\"},{\"t\":\"text\",\"v\":\" 讲一台机器上的进程、虚拟内存和锁。\"},{\"t\":\"link\",\"v\":\"计算机网络\",\"href\":\"../../cs-basics/05-networking/\"},{\"t\":\"text\",\"v\":\" 讲 IP、TCP 和 HTTP 的报文。\"},{\"t\":\"link\",\"v\":\"数据库基础\",\"href\":\"../../cs-basics/07-databases/\"},{\"t\":\"text\",\"v\":\" 讲单库里的 SQL 和事务。\"},{\"t\":\"link\",\"v\":\"微服务\",\"href\":\"../../microservices/07-distributed-transactions/\"},{\"t\":\"text\",\"v\":\" 讲 Saga、TCC 和 Outbox 怎么落地。那些章默认你已经知道：对方可能停了，而你还在跑，并且超时说明不了它到底做没做。本页只建立这个模型。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"有向图\",\"href\":\"../../cs-theory/10-digraphs-dag/\"},{\"t\":\"text\",\"v\":\" 里的偏序和 DAG 可以表示「谁先于谁」。那是依赖顺序的数学，不是本页的失效模型，也不是本页的前置。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"模型里有什么\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"一次运行由若干进程和它们之间的消息组成。这里的进程不是操作系统里的 \"},{\"t\":\"code\",\"v\":\"fork\"},{\"t\":\"text\",\"v\":\" 结果，而是一个会按自己的步调执行、并且可能停住的计算体。进程之间没有共享内存。谁要影响谁，只能送出一条消息，对方以后可能收到。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本页采用完全异步这个假设，沿用 Fischer、Lynch 与 Paterson 1985 年论文里的说法：不假设消息延迟有上界，也不假设各进程的相对速度有上界。局域网里延迟常常有经验上界。那是另一个模型。把异步模型里推不出的结论，说成「所以生产网络也永远做不到」，就换了假设。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"部分失效是这个模型的基本现象：一个进程可以停住，其余进程继续执行。一台机器的内核如果整体停摆，那台机器上的进程会一起停。分布式模型讨论的是另一种情况：系统的一部分停了，另一部分还在对外服务。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"超时不能区分两种历史\",\"id\":\"h-3\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"两个账户服务 A 和 B。客户端请 A 扣款，并请 B 入账。客户端把请求发给 A 之后，在自己选定的时限里没有收到响应。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"至少有两种与客户端所见相容的历史：\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"消息还在路上，或者 A 已经扣款但响应丢了。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"A 在处理之前就停了，扣款没有发生。\"}],\"n\":2}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"客户端无法从「超时」这一件事推出是哪一种。再发一次请求，可能把一次扣款变成两次，除非请求本身带有服务端能认出的唯一编号。TCP 保证的是一条连接上的字节流，连接还在、并且双方都按协议收发的时候才谈得上可靠送达。\"},{\"t\":\"link\",\"v\":\"计算机网络\",\"href\":\"../../cs-basics/05-networking/\"},{\"t\":\"text\",\"v\":\" 里的 TCP 没有提供「对方进程已经崩溃」这个信号。异步模型里甚至不假设你能发现对方已死：论文写明，若能探测进程死亡，他们的不可能结论就不成立。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"安全性质和活性\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"安全性质要求某类坏事永远不发生。活性要求某类好事终会发生。Fischer、Lynch 与 Paterson 的论文用两个专门术语来写这件事，不要把它们换成后来文献里常见的 validity。validity 通常要求：同一次运行的决定值必须等于该次运行中某个进程的输入。论文没有把这条写成部分正确的条件。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"论文第 2 节里，每个进程有一位输入寄存器。配置包括各进程的内部状态和消息缓冲。初始配置中每个进程处于初始状态，缓冲为空。从某个初始配置经有限步能到达的配置，称为可及配置。某个进程的输出寄存器为 0 或 1 时，该配置具有这个决定值。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"同一节（刊印页 377）规定，协议部分正确当且仅当：\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"任何可及配置里的决定值不超过一个。已作出的决定彼此相同。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"对 \"},{\"t\":\"code\",\"v\":\"{0,1}\"},{\"t\":\"text\",\"v\":\" 中的每一个 v，存在某个可及配置，其决定值是 v。两种决定值都在可及配置的全体里出现过。\"}],\"n\":2}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"第 2 条是非平凡性，范围是可及配置的集合，不是同一次运行。它不要求该次运行的决定值来自该次运行的某个输入。一个永远只决定 0 的协议违反第 2 条。一个在全体输入都是 0 的运行里决定 1 的协议，论文的第 2 条并不因此禁止它。本页不把这种「决定值来自本次输入」称作论文已经证明的性质。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"无故障指该进程在这次运行中走无穷步，否则称为故障。允许的运行至多有一个故障进程，并且发给无故障进程的消息最终都会被收到。有进程在该运行中进入决定状态，才叫这次运行作出了决定。尽管有一个故障仍完全正确，是指协议部分正确，并且每一次允许的运行都作出决定。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"第 3 节定理 1（刊印页 377）说：没有共识协议是尽管有一个故障仍完全正确的。证明先假设存在这样的协议，再得到一条允许的运行，其中决定永远不出现。办不到的是：在这个完全异步模型里，同时保住上面的部分正确，又让每条允许的运行都终止于一个决定。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这不是「任何一致都不可能」，也不是「安全性质不可能」。刊印页 381 的定理 2 给出一个部分正确的协议：若执行过程中没有进程死亡，并且开始时严格多数进程活着，则未停进程都会决定。随机化、部分同步或故障探测器都会改变原定理的假设。本文不进一步证明此时可解，也不能把定理 1 的原话搬到那些假设上。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"微服务\",\"href\":\"../../microservices/07-distributed-transactions/\"},{\"t\":\"text\",\"v\":\" 里的 Saga 和 Outbox 是业务层的做法：它们放弃「所有参与者同时提交或同时回滚」，改成可补偿或可靠地发出事件。那不是 FLP 定理的一种实现，也不说明 FLP 的前提在那些系统里成立。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"常见误读\",\"id\":\"h-5\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"「用了 TCP，超时就等于对方没做」。超时只说明响应没有在本地时限内到达。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「操作系统时钟的时间戳能给所有事件排成全序」。时钟会偏差。本页不把墙上时钟当作逻辑顺序。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「异步模型证明了任何网络都不能达成一致」。定理依赖完全异步、确定性协议，以及必须在每条允许运行里终止。换掉其中一条，结论要重新证明。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「单库事务已经解决了部分失效」。单库事务的提交点在一个数据库里。\"},{\"t\":\"link\",\"v\":\"数据库基础\",\"href\":\"../../cs-basics/07-databases/\"},{\"t\":\"text\",\"v\":\" 不讨论两个独立进程各有各的提交点。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"可选核对\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"不打开下面的答案，上一节的定义也已经完整。这两问只用来核对模型边界。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"客户端等待 A 超时。能不能据此断定 A 没有扣款？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"把消息延迟改成「最多 100 毫秒」，FLP 的定理 1 还是不是原话？\"}],\"n\":2}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"不能。响应可能在扣款之后丢失，也可能请求根本没被处理。两种历史都和超时相容。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"不是。定理依赖完全异步，也就是不设延迟上界。加上有限上界就是另一个模型，原证明不再直接适用。\"}],\"n\":2}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引\",\"id\":\"h-7\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"Fischer, Lynch, Paterson：Impossibility of Distributed Consensus with One Faulty Process\",\"href\":\"https://groups.csail.mit.edu/tds/papers/Lynch/jacm85.pdf\"},{\"t\":\"text\",\"v\":\" — JACM 1985，刊印页 377 的第 2 节定义部分正确：决定值唯一，且 0 和 1 各自出现在某个可及配置。第 3 节定理 1：没有协议在一个故障下完全正确。页 381 的定理 2 仍给出部分正确的协议。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"计算机网络：TCP\",\"href\":\"../../cs-basics/05-networking/\"},{\"t\":\"text\",\"v\":\" — 字节流和连接，不提供进程崩溃信号。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"微服务：分布式事务\",\"href\":\"../../microservices/07-distributed-transactions/\"},{\"t\":\"text\",\"v\":\" — Saga、TCC、Outbox 的工程做法，不是本页定理的复述。\"}]}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"这一页补哪一块\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"模型里有什么\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"超时不能区分两种历史\"},{\"id\":\"h-4\",\"level\":2,\"text\":\"安全性质和活性\"},{\"id\":\"h-5\",\"level\":2,\"text\":\"常见误读\"},{\"id\":\"h-6\",\"level\":2,\"text\":\"可选核对\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"资料索引\"}]},\"devops/01-repeatability\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"DevOps\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 可重复性\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"可重复性是一份合同：声明过的输入和步骤没变，制品的身份就不应悄悄改掉。它不保证程序正确。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"这一页补哪一块 {#repeatability-scope}\",\"id\":\"h-1\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"容器与编排\",\"href\":\"../../microservices/12-containers-k8s/\"},{\"t\":\"text\",\"v\":\" 写镜像怎么做、集群里怎么跑。\"},{\"t\":\"link\",\"v\":\"持续交付与 GitOps\",\"href\":\"../../microservices/14-cicd-gitops/\"},{\"t\":\"text\",\"v\":\" 已经把「不要用可变的 \"},{\"t\":\"code\",\"v\":\"latest\"},{\"t\":\"text\",\"v\":\" 做生产晋级」写成实践要点。本页补这条规则为什么属于可重复性，而不是某一种工具的癖好。不写 Dockerfile，不写工作流 YAML，也不教镜像分层。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"合同：输入没变，身份就不该悄悄变 {#repeatability-contract}\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"把「可重复」说成流水线可以签署的合同。合同列出这次承认的源修订、依赖、工具和步骤。这些有一项变了，产物就允许变。它们都没变，产物的身份不应在无人改声明的情况下换成另一件。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"身份在这里指制品的不可变摘要，不是一个以后还能改指向的名字。摘要变了，就是另一件制品。这条合同还不说这件制品的行为对不对，只说「我们承认的是哪一份字节」。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"三个层次不要混用 {#repeatability-layers}\",\"id\":\"h-3\"},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"层次\"}],[{\"t\":\"text\",\"v\":\"合同实际说了什么\"}],[{\"t\":\"text\",\"v\":\"流水线能不能拿它当保证\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"比特级可复现\"}],[{\"t\":\"text\",\"v\":\"相同源码、构建环境和构建指令，任何人都能得到逐字节相同的制品\"}],[{\"t\":\"text\",\"v\":\"可以。这是最强的一档\"}]],[[{\"t\":\"text\",\"v\":\"输入受控的可重复构建\"}],[{\"t\":\"text\",\"v\":\"工具和依赖被钉住，身份不应因未声明的输入漂移；时间戳等非输入因素仍可能让字节不同\"}],[{\"t\":\"text\",\"v\":\"可以承诺「输入没被偷换」，不能单凭这一点承诺字节全同\"}]],[[{\"t\":\"text\",\"v\":\"在我这台机器上能过\"}],[{\"t\":\"text\",\"v\":\"某一次、某一台机器上的步骤当时通过了\"}],[{\"t\":\"text\",\"v\":\"不可以。这不是对下一次的合同\"}]]]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"比特级这一档的定义来自 Reproducible Builds：给定相同的源代码、构建环境和构建指令，任何一方都能重新得到逐字节相同的指定制品。中间这一档是流水线更常见的承诺：把会移动的输入钉住。最弱的一档只是一次观察，下一次换机器或换一天，合同里没有写要相同。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"构建一次，此后只搬动制品 {#repeatability-once}\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"「构建一次，此后只搬动制品」是上面那份合同的推论。预发验证的是制品 A。生产若直接运行 A，验过的就是要上的。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"若预发和生产各自再编译一次，即使提交号相同，也不能再说生产验证过的是预发那一份。两次构建可以因为未钉住的输入而得到不同摘要。即便某次碰巧得到相同字节，这条流水线也没有把「同一份」写成它要遵守的约定，除非它接着比较摘要并拒绝不一致。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"容器不是可重复性本身 {#repeatability-image}\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"容器镜像可以是一件不可变制品，从而帮这条保证落地：上线时搬动的是一个摘要，而不是在目标机器上再编译。镜像怎么写、集群里怎么跑，仍见 \"},{\"t\":\"link\",\"v\":\"容器与编排\",\"href\":\"../../microservices/12-containers-k8s/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"「用了容器」推不出「构建已经可重复」。浮动的基础镜像，或没有钉住的软件包，会在同一次提交下给出不同摘要。保证在未钉住的那一项输入上被撤回。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"同一次提交，只改基座怎么引用：\"}]},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"基座\"}],[{\"t\":\"text\",\"v\":\"两次构建的制品摘要\"}],[{\"t\":\"text\",\"v\":\"保证停在哪\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"会移动的 \"},{\"t\":\"code\",\"v\":\"latest\"}],[{\"t\":\"text\",\"v\":\"可以不同。基座字节可能已经换过\"}],[{\"t\":\"text\",\"v\":\"在「基座是一项输入」这一步被撤回\"}]],[[{\"t\":\"text\",\"v\":\"钉在摘要上，其余声明的输入也没变\"}],[{\"t\":\"text\",\"v\":\"不能再把差异归因于基座悄悄移动\"}],[{\"t\":\"text\",\"v\":\"仍只达到输入受控。时间戳一类非输入因素还可能让字节不同\"}]]]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"钉住摘要没有自动升级成比特级可复现。它只是把这一项输入放回合同里。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"这条保证不覆盖的东西 {#repeatability-limits}\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"可重复性不保证程序正确，不保证依赖没有漏洞，也不保证换一个运行环境后行为不变。正确和测试证据在 \"},{\"t\":\"link\",\"v\":\"晋级与门禁\",\"href\":\"../03-promotion-gating/\"},{\"t\":\"text\",\"v\":\"，依赖和构建者的陈述在 \"},{\"t\":\"link\",\"v\":\"来源与追溯\",\"href\":\"../02-provenance/\"},{\"t\":\"text\",\"v\":\"。行为随环境变化，是另一份约定，不是「字节相同」能单独证明的。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"一次流水线是绿的，只说明这一次的步骤通过了。下次是否得到同一件制品，取决于输入有没有被钉住。锁了语言版本也不够：基座、系统包、构建器本身，都还是合同里的输入。漏钉一项，身份就可以在同一次提交下改变。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"常见误读 {#repeatability-misreadings}\",\"id\":\"h-7\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"「容器化了，构建就一定可重复。」镜像可以承载不可变制品。浮动基座或未钉住的包仍会在同一次提交下改掉摘要。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「在生产环境再编译一次更保险。」再编译撤回的是「生产跑的就是预发验过的那一份」。提交号相同填不上这个空缺。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「这次流水线是绿的，所以下一次也会得到同一件制品。」绿只说明这一次步骤通过，不等于输入已被钉住。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「锁了语言版本就够了。」语言版本只是一项输入。基座、系统包和构建器没钉住，合同仍然是开着的。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"可选核对 {#repeatability-check}\",\"id\":\"h-8\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"合同已经写在上面。这两问只核对它在哪一步还成立。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"同一次提交，基座从浮动的 \"},{\"t\":\"code\",\"v\":\"latest\"},{\"t\":\"text\",\"v\":\" 改成钉住的摘要。这是否已经证明两次构建的字节全同？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"预发和生产用同一提交号各编译一次。能不能说生产验证过的就是预发那一份？\"}],\"n\":2}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"还不能。钉住摘要只是收回「基座可以悄悄移动」这一项。比特级全同还要求构建环境和指令也不引入未声明的差异，例如会变的时间戳。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"不能。各自再编译时，流水线没有把同一件制品从预发搬到生产。提交号相同不等于摘要相同。\"}],\"n\":2}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引 {#repeatability-sources}\",\"id\":\"h-9\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"Reproducible Builds：定义\",\"href\":\"https://reproducible-builds.org/docs/definition/\"},{\"t\":\"text\",\"v\":\" — 比特级可复现：相同源码、构建环境和构建指令，应得到逐字节相同的制品。本页的另外两档是相对这条定义划出的更弱合同，不是该站的分级表。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Jez Humble 与 David Farley, Continuous Delivery\",\"href\":\"https://continuousdelivery.com/\"},{\"t\":\"text\",\"v\":\" — 「构建一次，再把同一件制品晋级」是部署流水线的保证，不是某个 CI 产品的功能。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"OCI 镜像描述符\",\"href\":\"https://github.com/opencontainers/image-spec/blob/main/descriptor.md\"},{\"t\":\"text\",\"v\":\" — 制品身份用内容摘要，而不是一个以后还能改指向的标签。引用的是身份约定，不是镜像怎么写。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"容器与编排\",\"href\":\"../../microservices/12-containers-k8s/\"},{\"t\":\"text\",\"v\":\" — 镜像作为制品形态。本页不重复构建步骤。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"持续交付与 GitOps\",\"href\":\"../../microservices/14-cicd-gitops/\"},{\"t\":\"text\",\"v\":\" — 实践里不用可变的 \"},{\"t\":\"code\",\"v\":\"latest\"},{\"t\":\"text\",\"v\":\" 做生产晋级。本页说明这是可重复性，不是工具癖好。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"返回 DevOps\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：来源与追溯\",\"href\":\"../02-provenance/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"这一页补哪一块 {#repeatability-scope}\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"合同：输入没变，身份就不该悄悄变 {#repeatability-contract}\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"三个层次不要混用 {#repeatability-layers}\"},{\"id\":\"h-4\",\"level\":2,\"text\":\"构建一次，此后只搬动制品 {#repeatability-once}\"},{\"id\":\"h-5\",\"level\":2,\"text\":\"容器不是可重复性本身 {#repeatability-image}\"},{\"id\":\"h-6\",\"level\":2,\"text\":\"这条保证不覆盖的东西 {#repeatability-limits}\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"常见误读 {#repeatability-misreadings}\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"可选核对 {#repeatability-check}\"},{\"id\":\"h-9\",\"level\":2,\"text\":\"资料索引 {#repeatability-sources}\"}]},\"devops/02-provenance\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"DevOps\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 来源与追溯\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"来源证据回答一件制品是谁、用哪些材料、从哪一次源修订、由谁做出来的。它是可核对的陈述，不是安全结论。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"这一页补哪一块 {#provenance-scope}\",\"id\":\"h-1\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"Git 版本控制\",\"href\":\"../../cs-basics/04-git/\"},{\"t\":\"text\",\"v\":\" 写提交、分支和 PR 怎么用。本页只取「修订身份」这一层，不重讲命令。\"},{\"t\":\"link\",\"v\":\"持续交付与 GitOps\",\"href\":\"../../microservices/14-cicd-gitops/\"},{\"t\":\"text\",\"v\":\" 已把不可变标签和「期望状态放进 Git」写成实践。本页说明：没有稳定的制品身份，后面的晋级、回滚和审计都失去对象。不写 SBOM 格式教程，也不做签名工具对照表。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"来源要回答的那几个问题 {#provenance-questions}\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"一份来源证据要能回答固定的一组问题：哪一次源修订，哪份构建定义，哪些输入，由哪个构建者，在什么时候，产出了哪一个制品身份。身份是摘要，不是一个以后还会改指向的标签。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"少一项，后面的人就无法把「当时承认的那一份」和「现在这个名字指向的那一份」对上。SLSA 用 provenance 这类证明来承载这种陈述，并说明如何验证它。本页只用这组词汇。它不是一份逐级要勾选的合规清单。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"v1.2 相对 v1.1 增加了 Source Track。源修订本身也可以有保证等级，例如历史是否被保留、这次修订是怎么产生的。这里只点明有这一档，不展开各级条款。2026-11-10 核对 \"},{\"t\":\"link\",\"v\":\"官方说明\",\"href\":\"https://slsa.dev/spec/v1.2/\"},{\"t\":\"text\",\"v\":\"，现行批准版仍是 v1.2，状态为 Approved。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"提交号不是完整的构建来源 {#provenance-git}\",\"id\":\"h-3\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"Git 提交号是源修订的名字。它指出那一次快照的内容身份。它不自动包含工具链、依赖锁定和构建环境，也不自动阻止以后有人把分支名改指向另一次提交。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"所以「仓库里看得到这个哈希」只完成了来源问题里的第一问。构建定义、输入和构建者仍要另有陈述。命令和分支怎么用，仍以 \"},{\"t\":\"link\",\"v\":\"Git 版本控制\",\"href\":\"../../cs-basics/04-git/\"},{\"t\":\"text\",\"v\":\" 为准。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"身份钉在摘要上 {#provenance-digest}\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"制品身份用不可变摘要，不用 \"},{\"t\":\"code\",\"v\":\"latest\"},{\"t\":\"text\",\"v\":\" 这类会改指向的名字。两个时刻可以共用同一个标签，摘要却不同。标签回答不了「哪一份被承认过」。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"没有稳定身份时，晋级无法说明搬过去的是验过的那一件，回滚无法指回旧的那一件，审计也无法在事后复述当时放行的是谁。镜像作为这种制品的一种形态，见 \"},{\"t\":\"link\",\"v\":\"容器与编排\",\"href\":\"../../microservices/12-containers-k8s/\"},{\"t\":\"text\",\"v\":\"，本页不讲构建指令。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"短例子：标签 \"},{\"t\":\"code\",\"v\":\"app:release\"},{\"t\":\"text\",\"v\":\" 在周一指向摘要 D1，在周二指向摘要 D2。界面上两次都能「看到一个 SHA」，但看到的不是同一件制品。只有绑在 D1 上的来源陈述，才能判断 D1 被承认过；D2 要有自己的陈述。共用的标签证明不了这件事。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"证明是陈述，不是结论 {#provenance-statement}\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"构建来源证明和材料清单（SBOM 一类）都是关于制品的陈述。陈述可以核对：它声称的修订、材料和构建者，是否和签名、摘要对得上。核对通过，只说明这份陈述没有被换成另一份，以及它说的是这一个摘要。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"它不能单独推出「软件是安全的」或「软件是正确的」。材料清单列出用了哪些组件。列出来，不等于这些组件没有漏洞，也不等于程序做对了要做的事。SPDX 和 CycloneDX 都是在描述这种清单，本页不选哪一种格式。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"签名把「身份」和「陈述」绑在一起。签的是摘要，验的是谁被信任。信任的是签发这张陈述的那一方，不是「因此有人审过代码」。签过名仍可能只是构建者在声明自己做了这次构建。把签名当成批准，是换了一个问题。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"部署来源不能顶替构建来源 {#provenance-gitops}\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"部署侧和构建侧要分开。GitOps 把期望状态放进 Git，集群持续收敛到那份声明。它回答的是「集群在按谁声明的状态运行」。OpenGitOps 把这件事定义为原则；实践见 \"},{\"t\":\"link\",\"v\":\"持续交付与 GitOps\",\"href\":\"../../microservices/14-cicd-gitops/\"},{\"t\":\"text\",\"v\":\"，本页不重抄工具对照。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这份部署来源不能顶替「这个镜像是从哪次构建来的」。期望状态里即使写了一个镜像名，只要那个名字还能改指向，构建来源的问题就还在。两边都要有，而且指的不是同一层。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"常见误读 {#provenance-misreadings}\",\"id\":\"h-7\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"「有 commit 哈希，来源就齐了。」提交号只命名源修订。工具链、依赖和构建者不在这个哈希里。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「有 SBOM 就说明软件安全。」清单是一份可核对的材料陈述，不是漏洞或正确性的结论。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「界面上能看到 SHA，所以用 \"},{\"t\":\"code\",\"v\":\"latest\"},{\"t\":\"text\",\"v\":\" 也没关系。」标签会改指向。周一的 SHA 和周二的 SHA 可以不同，而名字没变。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「签过名就是正确的、被批准的。」签名核验的是谁被信任、签的是哪个摘要。它不自动等于有人审过代码。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"可选核对 {#provenance-check}\",\"id\":\"h-8\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"问题已经列在上面。这两问只核对哪一层证据还缺。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"一件制品带有 Git 提交号和一份材料清单。来源问题是否已经答完？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"两个镜像先后都叫 \"},{\"t\":\"code\",\"v\":\"app:release\"},{\"t\":\"text\",\"v\":\"，摘要不同。能不能用这个标签判断哪一份被承认过？\"}],\"n\":2}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"还没有。提交号是源修订，材料清单是组件陈述。构建定义、构建者和制品摘要之间的绑定还要单独写明，并说明谁被信任来签发这张陈述。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"不能。标签是会改指向的名字。只有绑在某一个摘要上的来源陈述，才能判断那一份被承认过。\"}],\"n\":2}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引 {#provenance-sources}\",\"id\":\"h-9\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"SLSA v1.2\",\"href\":\"https://slsa.dev/spec/v1.2/\"},{\"t\":\"text\",\"v\":\" — 2026-11-10 核对，状态为 Approved。provenance 是关于制品如何产生的证明，验证的是这张陈述。本页不逐级勾选。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"SLSA v1.2：What's new\",\"href\":\"https://slsa.dev/spec/v1.2/whats-new\"},{\"t\":\"text\",\"v\":\" — 相对 v1.1 增加 Source Track。正文只记下「源修订本身也可以有保证等级」，不展开条款。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"SLSA v1.2 发布说明\",\"href\":\"https://slsa.dev/blog/2025/11/announce-slsa-v1.2\"},{\"t\":\"text\",\"v\":\" — 2025-11-24 宣布 v1.2。以官方说明页的 Approved 状态为准，不以仓库的 Latest 标签为准。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"in-toto\",\"href\":\"https://in-toto.io/\"},{\"t\":\"text\",\"v\":\" — 供应链上的证明是经过认证的陈述。陈述可核对，不等于软件因此安全或正确。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"SPDX\",\"href\":\"https://spdx.dev/\"},{\"t\":\"text\",\"v\":\" 与 \"},{\"t\":\"link\",\"v\":\"CycloneDX\",\"href\":\"https://cyclonedx.org/\"},{\"t\":\"text\",\"v\":\" — 材料清单的两种写法。本页只取「清单是陈述」，不选格式。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"OpenGitOps 原则\",\"href\":\"https://opengitops.dev/\"},{\"t\":\"text\",\"v\":\" — 部署来源：期望状态被声明并持续收敛。不能顶替构建来源。微服务 14 已引，这里只对照。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Git 版本控制\",\"href\":\"../../cs-basics/04-git/\"},{\"t\":\"text\",\"v\":\" — 修订身份怎么用。本页不重讲命令。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"持续交付与 GitOps\",\"href\":\"../../microservices/14-cicd-gitops/\"},{\"t\":\"text\",\"v\":\" — 不可变标签，以及 Git 里的期望状态。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"容器与编排\",\"href\":\"../../microservices/12-containers-k8s/\"},{\"t\":\"text\",\"v\":\" — 镜像作为制品。不讲构建指令。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：可重复性\",\"href\":\"../01-repeatability/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回 DevOps\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：晋级与门禁\",\"href\":\"../03-promotion-gating/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"这一页补哪一块 {#provenance-scope}\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"来源要回答的那几个问题 {#provenance-questions}\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"提交号不是完整的构建来源 {#provenance-git}\"},{\"id\":\"h-4\",\"level\":2,\"text\":\"身份钉在摘要上 {#provenance-digest}\"},{\"id\":\"h-5\",\"level\":2,\"text\":\"证明是陈述，不是结论 {#provenance-statement}\"},{\"id\":\"h-6\",\"level\":2,\"text\":\"部署来源不能顶替构建来源 {#provenance-gitops}\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"常见误读 {#provenance-misreadings}\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"可选核对 {#provenance-check}\"},{\"id\":\"h-9\",\"level\":2,\"text\":\"资料索引 {#provenance-sources}\"}]},\"devops/03-promotion-gating\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"DevOps\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 晋级与门禁\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"晋级把一件已被承认的制品和它的证据送进下一个环境。门禁只保证它实际检查过的那条命题。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"这一页补哪一块 {#promotion-scope}\",\"id\":\"h-1\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"持续交付与 GitOps\",\"href\":\"../../microservices/14-cicd-gitops/\"},{\"t\":\"text\",\"v\":\" 写晋级实践和渐进交付怎么做。\"},{\"t\":\"link\",\"v\":\"测试\",\"href\":\"../../microservices/15-testing/\"},{\"t\":\"text\",\"v\":\" 与 \"},{\"t\":\"link\",\"v\":\"Java 08\",\"href\":\"../../java/08-testing/\"},{\"t\":\"text\",\"v\":\" 写测试金字塔和契约测试。\"},{\"t\":\"link\",\"v\":\"可观测性\",\"href\":\"../../microservices/10-observability/\"},{\"t\":\"text\",\"v\":\" 写指标、日志和链路。本页只讨论这些东西适合当作哪一种证据，以及「允许进入」到底检查了什么。不写云账号，不把环境讲成厂商产品名，也不重写金丝雀的 YAML。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"环境是信任的台阶 {#promotion-steps}\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"环境是信任的台阶，不是目录标签。从预发到生产，晋级移动的是同一件制品及其证据，而不是「用同一提交在新环境里再做一次」。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这和 \"},{\"t\":\"link\",\"v\":\"可重复性\",\"href\":\"../01-repeatability/\"},{\"t\":\"text\",\"v\":\" 是同一份合同的下一句。那里保证输入没变时身份不悄悄改变。这里保证往前走的就是那一个身份，而不是一个新编出来的近亲。来源陈述如何绑到这个身份上，见 \"},{\"t\":\"link\",\"v\":\"来源与追溯\",\"href\":\"../02-provenance/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"门禁只覆盖它检查过的命题 {#promotion-gates}\",\"id\":\"h-3\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"门禁是进入下一台阶所需的证据。它可以是自动检查、人工审批，或一条安全、变更策略。每一种只保证它实际检查过的命题。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"流水线变绿，只等于所列检查当时通过。它不等于系统在生产里正确，也不等于没有跑到的路径是安全的。没写进门禁的命题，这次放行没有覆盖。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"人工审批首先是责任门禁：它记录谁在何时放行。除非同时写清审批人必须看哪一份证据，否则它不自动变成技术保证。点了批准，可能只说明有人在场，不说明摘要被核对过、测试被看过。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"测试结果是一种证据 {#promotion-tests}\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"测试结果是常见的一种证据。单元测试、契约测试各自能挡住的失败不一样。分层和契约怎么写，见 \"},{\"t\":\"link\",\"v\":\"微服务 15\",\"href\":\"../../microservices/15-testing/\"},{\"t\":\"text\",\"v\":\" 和 \"},{\"t\":\"link\",\"v\":\"Java 08\",\"href\":\"../../java/08-testing/\"},{\"t\":\"text\",\"v\":\"，本页不重复。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"适合挡在哪一级，取决于那一级要相信什么。还没离开构建的台阶，适合挡住「这件制品连自己的单元约定都不满足」。进入预发之前，适合挡住「它和上下游的契约对不上」。这些检查没跑到的路径，不会因为流水线是绿的就被覆盖。门禁的边界就是测试实际执行过的那一组命题。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"流量晋级不是制品晋级 {#promotion-traffic}\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"渐进交付把流量也当作晋级对象。金丝雀或蓝绿先把一小部分流量交给这件制品，再扩大。它保证的是：风险先暴露在限定范围内，而不是一开始就面对全部用户。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"它不替代制品晋级。顺序是先有同一份制品，再切流量。没有「验过的就是要上的」这一条，切流量只是在切一份还没被承认的新构建。步骤和自动回滚条件的写法见 \"},{\"t\":\"link\",\"v\":\"微服务 14\",\"href\":\"../../microservices/14-cicd-gitops/\"},{\"t\":\"text\",\"v\":\"。切流时可以看的信号见 \"},{\"t\":\"link\",\"v\":\"可观测性\",\"href\":\"../../microservices/10-observability/\"},{\"t\":\"text\",\"v\":\"，本页不讲采集栈。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"搬过去，还是再编一次 {#promotion-contrast}\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"对照两条路。预发验过制品 A：\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"晋级：生产运行 A，来源证据跟着 A 走。验过的就是要上的。门禁若要求摘要一致，换一件就会被拒绝。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"重建：生产用同一提交再编译出 A′。即使提交号相同，A′ 也是另一件制品，除非摘要被证明相同。预发的验证不再自动覆盖生产正在跑的那一份。\"}],\"n\":2}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"第二条撤回的就是本章要守的约定。它不是「针对该环境做了更严格的验证」。环境差异要另写检查；用重新构建来冒充那项检查，两件事都没做成。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"常见误读 {#promotion-misreadings}\",\"id\":\"h-7\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"「流水线全绿，生产就不会出事。」绿只等于所列检查当时通过。没写进门禁的命题，这次放行没有覆盖。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「每个环境重新构建，才叫针对该环境做了验证。」重新构建撤回的是「验过的就是要上的」。环境差异要另作检查，不能靠再编译来冒充。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「有人点了批准，就等于做过技术检查。」审批记录的是谁在何时放行。只有写明必须看的证据，它才同时是技术门禁。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「金丝雀是发布工具的功能，和晋级策略无关。」它是把流量当作晋级对象：先在限定范围内暴露风险。它仍然要求先有同一份制品。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"可选核对 {#promotion-check}\",\"id\":\"h-8\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"台阶和门禁已经分开写了。这两问只核对放行覆盖了哪一条。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"所有自动检查都绿了，又有人点了批准，但审批说明里没有要求核对制品摘要。这次放行保证了摘要没被换成另一件吗？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"生产用同一提交重新构建，再把 5% 的流量切过去。这是制品晋级吗？\"}],\"n\":2}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"不保证。自动检查只覆盖它们实际跑过的命题。没写明「必须核对摘要」的批准，记录的是有人放行，不是摘要身份。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"不是。重新构建得到的是另一件制品，除非摘要被证明相同。切 5% 流量是流量晋级，它不能把一次新构建说成预发验过的那一份。\"}],\"n\":2}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引 {#promotion-sources}\",\"id\":\"h-9\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"Jez Humble 与 David Farley, Continuous Delivery\",\"href\":\"https://continuousdelivery.com/\"},{\"t\":\"text\",\"v\":\" — 部署流水线的各阶段是信任台阶：同一件制品凭证据晋级，而不是每个环境重新编译。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"OpenGitOps 原则\",\"href\":\"https://opengitops.dev/\"},{\"t\":\"text\",\"v\":\" — 期望状态可以被声明和收敛。本页只用它区分「状态晋级」和「流量晋级」，不重复工具对照。微服务 14 已引这份原则。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"持续交付与 GitOps\",\"href\":\"../../microservices/14-cicd-gitops/\"},{\"t\":\"text\",\"v\":\" — 晋级实践和渐进交付的步骤。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"测试\",\"href\":\"../../microservices/15-testing/\"},{\"t\":\"text\",\"v\":\" — 分层和契约测试。本页只把结果当作门禁证据。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Java 08 测试\",\"href\":\"../../java/08-testing/\"},{\"t\":\"text\",\"v\":\" — 单元测试基础，不重复。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"可观测性\",\"href\":\"../../microservices/10-observability/\"},{\"t\":\"text\",\"v\":\" — 门禁或切流可以看的信号。不讲采集栈。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：来源与追溯\",\"href\":\"../02-provenance/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回 DevOps\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：回滚与审计\",\"href\":\"../04-rollback-audit/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"这一页补哪一块 {#promotion-scope}\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"环境是信任的台阶 {#promotion-steps}\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"门禁只覆盖它检查过的命题 {#promotion-gates}\"},{\"id\":\"h-4\",\"level\":2,\"text\":\"测试结果是一种证据 {#promotion-tests}\"},{\"id\":\"h-5\",\"level\":2,\"text\":\"流量晋级不是制品晋级 {#promotion-traffic}\"},{\"id\":\"h-6\",\"level\":2,\"text\":\"搬过去，还是再编一次 {#promotion-contrast}\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"常见误读 {#promotion-misreadings}\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"可选核对 {#promotion-check}\"},{\"id\":\"h-9\",\"level\":2,\"text\":\"资料索引 {#promotion-sources}\"}]},\"devops/04-rollback-audit\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"DevOps\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 回滚与审计\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"回滚撤回的是一次已经承认的晋级。审计留下的是当时谁、凭什么、把哪一份制品放进或撤出了哪个环境。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"这一页补哪一块 {#rollback-scope}\",\"id\":\"h-1\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"前两章已经定义制品身份和晋级：\"},{\"t\":\"link\",\"v\":\"来源与追溯\",\"href\":\"../02-provenance/\"},{\"t\":\"text\",\"v\":\" 说明摘要上绑着什么陈述，\"},{\"t\":\"link\",\"v\":\"晋级与门禁\",\"href\":\"../03-promotion-gating/\"},{\"t\":\"text\",\"v\":\" 说明同一份制品怎样进入下一环境。本章只写怎样撤回那一次进入，以及怎样在事后复述它。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"持续交付与 GitOps\",\"href\":\"../../microservices/14-cicd-gitops/\"},{\"t\":\"text\",\"v\":\" 写自动回滚条件怎么配。\"},{\"t\":\"link\",\"v\":\"可观测性\",\"href\":\"../../microservices/10-observability/\"},{\"t\":\"text\",\"v\":\" 写信号从哪来。\"},{\"t\":\"link\",\"v\":\"分布式事务\",\"href\":\"../../microservices/07-distributed-transactions/\"},{\"t\":\"text\",\"v\":\" 写补偿怎么落地。\"},{\"t\":\"link\",\"v\":\"分布式系统模型\",\"href\":\"../../systems/distributed/\"},{\"t\":\"text\",\"v\":\" 写部分失效，以及超时说明不了对方做没做。本页不重写这些模型，也不做事故管理手册。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"回滚的对象是先前那件制品 {#rollback-object}\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"回滚的对象是先前已经承认的制品，不是「把 Git 再 revert 一次，指望流水线长出差不多的东西」。能回滚的前提有三条，缺一条就不成立：旧制品还在，它的身份还在，来源证据还在。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"身份是摘要。证据是绑在这个摘要上的来源陈述和当时的门禁结果。只有这些还在，才能把环境指回「上一份被承认的那一件」，而不是指回一个新编译出来的近亲。\"},{\"t\":\"code\",\"v\":\"git revert\"},{\"t\":\"text\",\"v\":\" 产生的是一次新的源修订。它可能触发一次新构建，那是另一条晋级，不是撤回旧的那一次。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"什么时候这条保证还在 {#rollback-conditions}\",\"id\":\"h-3\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"回滚容易成立的条件：服务没有把自己的正确性绑在一套已经前移的数据格式上，协议对旧制品仍然向后兼容。典型情况是无状态服务，数据库还没有按新规则写入。此时把流量或期望状态指回旧摘要，请求仍按旧约定被处理。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"保证被撤回的条件是下面任何一条已经发生：模式已经前进一步，数据已经按新规则写入，或其他进程可能已经处理过新版本发出的消息。镜像可以回到旧摘要，业务状态不一定回得去。旧制品看到新数据，会按它自己的约定失败，或者更糟，把新数据读成旧格式。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"数据要怎样补偿，见 \"},{\"t\":\"link\",\"v\":\"分布式事务\",\"href\":\"../../microservices/07-distributed-transactions/\"},{\"t\":\"text\",\"v\":\" 里的 Saga 和 Outbox。那一章讲的是业务层的补偿，不是把镜像摘要换回去。超时也不等于没做：对方可能已经写入，只是响应没回来。\"},{\"t\":\"link\",\"v\":\"分布式系统模型\",\"href\":\"../../systems/distributed/\"},{\"t\":\"text\",\"v\":\" 说明这两种历史可以和同一次超时相容。所以「把镜像换回去」不能当成「分布式副作用已经撤销」。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"短例子：生产已经跑过一次不可逆迁移，新列被写入之后，再把镜像回到旧摘要。旧程序不认识这套数据，请求失败。对照：只回滚无状态服务，数据库尚未切换。旧制品面对的仍是它验证过的那套数据，回滚保证还在。差别不在镜像还在不在，而在数据有没有越过旧约定。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"自动回滚是写好的门禁反应 {#rollback-auto}\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"自动回滚是一种预先写好的门禁反应。例如错误率越过阈值，就把期望状态指回上一份制品。它依赖可观测信号。信号从哪来见 \"},{\"t\":\"link\",\"v\":\"可观测性\",\"href\":\"../../microservices/10-observability/\"},{\"t\":\"text\",\"v\":\"，阈值怎么配见 \"},{\"t\":\"link\",\"v\":\"微服务 14\",\"href\":\"../../microservices/14-cicd-gitops/\"},{\"t\":\"text\",\"v\":\" 的金丝雀条件。本页不讲采集栈。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"没有可靠信号时，自动回滚会撤回「越改越安全」的直觉。错误的阈值可以把一次正常发布打回去，也可以在真正出错时不动。它是否更安全，取决于信号是否在量那件要撤回的事，以及旧制品是否仍满足上一节的条件。信号不可靠，自动化只是更快地执行一个未成立的撤回。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"审计记录不是运行遥测 {#rollback-audit-log}\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"审计记录是流水线的产品之一。它要能复述：制品身份、来源证据、门禁结果、审批人、晋级和回滚的时间。事后核验靠这些陈述还在，而不是靠当事人回忆。SLSA 把验证定义为核对来源陈述；本页只取这一点，不把审计写成等级清单。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"集群里的运行遥测是另一份记录。它回答「系统此刻表现如何」。流水线审计回答「我们当时承认了什么」。错误率升高可以触发自动回滚，但那条曲线本身不是放行记录。把监控日志当成审计，会在要问「谁放行了摘要 D1」时只找到「CPU 当时是多少」。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"常见误读 {#rollback-misreadings}\",\"id\":\"h-6\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"「回滚就是 \"},{\"t\":\"code\",\"v\":\"git revert\"},{\"t\":\"text\",\"v\":\"。」revert 是一次新的源修订，往往引出一次新构建。回滚要指回仍然存在的旧制品及其证据。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「只要旧镜像还在，回滚就一定安全。」镜像可以回到旧摘要。数据或已发出的消息若已经按新规则往前走，旧制品的约定就不再成立。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「集群或监控里的日志，就是流水线的审计。」遥测回答系统表现如何。审计要回答当时承认了哪一份制品、谁放的行。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「自动回滚一定比不回滚更安全。」它只是按阈值执行撤回。信号不可靠，或旧制品已经配不上新数据，自动化不会把保证补回来。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"可选核对 {#rollback-check}\",\"id\":\"h-7\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"条件和记录已经分开写了。这两问只核对保证还在不在。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"旧镜像的摘要还在仓库里，生产的数据迁移已经写完。把流量指回旧摘要，回滚保证还成立吗？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"监控里能看到错误率曲线和容器日志。这是否就是「谁在何时放行了哪一个摘要」的审计？\"}],\"n\":2}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"不成立。旧制品还在，只满足身份那一条。数据已经按新规则写入，旧约定被撤回。镜像回到旧摘要，请求仍可能按新数据失败。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"不是。曲线和容器日志是运行遥测。审计要有制品身份、来源证据、门禁结果、审批人和时间。两份记录回答的不是同一个问题。\"}],\"n\":2}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引 {#rollback-sources}\",\"id\":\"h-8\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"Jez Humble 与 David Farley, Continuous Delivery\",\"href\":\"https://continuousdelivery.com/\"},{\"t\":\"text\",\"v\":\" — 回滚指回已经发布过的那件制品，发布记录要能复述当时放行了什么。引用的是这条保证，不是某个发布产品的操作步骤。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"SLSA v1.2\",\"href\":\"https://slsa.dev/spec/v1.2/\"},{\"t\":\"text\",\"v\":\" — 2026-11-10 核对仍为 Approved。验证是事后核验来源陈述。审计靠这些陈述还在，而不是靠回忆。不逐级勾选。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"持续交付与 GitOps\",\"href\":\"../../microservices/14-cicd-gitops/\"},{\"t\":\"text\",\"v\":\" — 实践中的自动回滚条件。期望状态的变更可以留下记录。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"可观测性\",\"href\":\"../../microservices/10-observability/\"},{\"t\":\"text\",\"v\":\" — 信号从哪来。信号不是审计本身。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"分布式事务\",\"href\":\"../../microservices/07-distributed-transactions/\"},{\"t\":\"text\",\"v\":\" — 数据已经前进一步时的补偿。不是把镜像摘要换回去。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"分布式系统模型\",\"href\":\"../../systems/distributed/\"},{\"t\":\"text\",\"v\":\" — 部分失效，以及超时不等于没做。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"来源与追溯\",\"href\":\"../02-provenance/\"},{\"t\":\"text\",\"v\":\" — 制品身份和来源陈述。本章直接依赖。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"晋级与门禁\",\"href\":\"../03-promotion-gating/\"},{\"t\":\"text\",\"v\":\" — 什么叫进入下一个环境。本章撤回的是那一次进入。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：晋级与门禁\",\"href\":\"../03-promotion-gating/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回 DevOps\",\"href\":\"../\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"这一页补哪一块 {#rollback-scope}\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"回滚的对象是先前那件制品 {#rollback-object}\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"什么时候这条保证还在 {#rollback-conditions}\"},{\"id\":\"h-4\",\"level\":2,\"text\":\"自动回滚是写好的门禁反应 {#rollback-auto}\"},{\"id\":\"h-5\",\"level\":2,\"text\":\"审计记录不是运行遥测 {#rollback-audit-log}\"},{\"id\":\"h-6\",\"level\":2,\"text\":\"常见误读 {#rollback-misreadings}\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"可选核对 {#rollback-check}\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"资料索引 {#rollback-sources}\"}]},\"product-research/01-problem-constraints\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"产品调研\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 问题与约束\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"记录先写清要决定什么，以及决定必须遵守哪些限制。缺了共同起点，后面的对照和选型没有东西可核。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"这一页补哪一块 {#problem-scope}\",\"id\":\"h-1\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本页只写「问题」和「约束」如何被记下来、以后如何核。访谈怎么做、问卷怎么抽样、人物画像怎么画，本批不写。已有技术栈的具体内容在 \"},{\"t\":\"link\",\"v\":\"Java\",\"href\":\"../../java/\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"link\",\"v\":\"微服务\",\"href\":\"../../microservices/\"},{\"t\":\"text\",\"v\":\" 和 \"},{\"t\":\"link\",\"v\":\"AI\",\"href\":\"../../ai/\"},{\"t\":\"text\",\"v\":\" 的主题首页，本页不重写那些章，也不跳进某一课的实现。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"问题要能被判定 {#problem-question}\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"问题是一个可判定的句子，不是愿望清单。至少写下三件：对象是谁、要改变的是哪一件事、怎样算解决。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"对象在本页只作为带来源的假设。来源可以是一次注明日期的观察，或一份已经公开的材料。没有来源的人物画像不能当作约束，也不能当作问题的对象。「为谁而做」若写不出来源，就还不是记录的一部分。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"要改变的事必须具体到一件可指认的状况，而不是「做得更好」。怎样算解决，要写成以后能核对的结果：哪一种状况不再出现，或哪一条限制被满足。缺了这三项里的任何一项，第 02 章没有共同的对照单位，第 03 章也没有可判定的问题可决定。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"「要完成的工作」和「解决方案清单」不是同一句话。人要在某种处境里取得进展，和手里已经列好的功能，是两类句子。本页只取这个区分，不写成某套方法论的教程。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"约束必须可核对 {#problem-constraints-check}\",\"id\":\"h-3\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"约束是判断必须遵守的条件：时间、已有技术边界、合规、人员或运行环境。它要能被核对。例如「必须跑在已经存在的 JVM 服务里」可以回到 \"},{\"t\":\"link\",\"v\":\"Java\",\"href\":\"../../java/\"},{\"t\":\"text\",\"v\":\" 里记下的边界去核。「要先进」「要体验好」不能核，所以不能当约束。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"技术栈已经选过，并不使约束自动存在。栈是事实。约束是「这次决定必须守住哪一条事实」。不把那条写下来，后来的人不知道当时哪些事实被当成了限制，哪些只是背景。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"观察、推断、决定 {#problem-sentences}\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"三类句子不能混写。\"}]},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"种类\"}],[{\"t\":\"text\",\"v\":\"记录里必须有的\"}],[{\"t\":\"text\",\"v\":\"不能写成\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"观察\"}],[{\"t\":\"text\",\"v\":\"来源和日期\"}],[{\"t\":\"text\",\"v\":\"由它推出来的原因\"}]],[[{\"t\":\"text\",\"v\":\"推断\"}],[{\"t\":\"text\",\"v\":\"从哪几条观察推出，推理是什么\"}],[{\"t\":\"text\",\"v\":\"一条没有来源的「事实」\"}]],[[{\"t\":\"text\",\"v\":\"决定\"}],[{\"t\":\"text\",\"v\":\"在哪些约束下做的取舍\"}],[{\"t\":\"text\",\"v\":\"观察本身\"}]]]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"把推断写成观察，是后面对照失真的常见起点。别人无法再分清「看见了什么」和「当时以为这意味着什么」。决定更不能冒充观察：取舍是判断，判断要挂在事实上，但判断不是事实。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"同一句话，两种约束 {#problem-example}\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"「要做离线可用」还不是一个问题。把它放进两种约束里，后面两章的起点就不同。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"现场没有网络，而且必须当场提交。要改变的是「当场交不出去」。解决是：在无网时仍能完成那一次提交。后面的对照要比的是离线提交，不是「看起来也能缓存」。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"通勤时看看已经缓存的内容。要改变的是「路上能不能读」。解决是：读得到上次同步的内容。提交可以等有网。离线写入不是这条约束要求的。\"}],\"n\":2}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"两句都可以叫「离线」。约束不同，第 02 章不能把它们放进同一格对照，第 03 章也不能共用一次选型。本页停在起点，不展开成方案。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"常见误读 {#problem-misreadings}\",\"id\":\"h-6\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"「先写功能列表，问题以后再补。」没有可判定的问题和约束，功能列表没有共同起点。以后补上的问题，往往是为了给已经写下的功能找理由。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「用户说想要什么，就是要解决的问题。」想要的常常是方案。问题要写成要改变的状况，以及怎样算解决。原话若被采用，只能作为带来源和日期的观察。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「技术栈已经选了，就不必再写约束。」栈是事实。这次决定守住哪一条，仍要写成可核对的约束。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「没有访谈记录，就不能开始写问题。」本页要的是可追溯的假设，不是一份完整的用研档案。没有来源的画像不能当约束；有来源的假设可以先写下，并标明它是假设。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"可选核对 {#problem-check}\",\"id\":\"h-7\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"三类句子已经分开。这两问只核对记录还缺不缺起点。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"记录写了「用户都希望离线可用」，没有来源，也没有写怎样算解决。它是一条可判定的问题吗？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"「必须跑在已有的 JVM 服务里」和「技术上要先进」，哪一条可以当约束？\"}],\"n\":2}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"不是。对象没有来源，怎样算解决也没写。它至多是一条未追溯的愿望，不能当第 02 章的共同起点。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"只有前一条。它可以回到已记录的 Java 边界去核。「要先进」没有可核对的条件。\"}],\"n\":2}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引 {#problem-sources}\",\"id\":\"h-8\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"Clayton Christensen 等：Know Your Customers' Jobs to Be Done\",\"href\":\"https://hbr.org/2016/09/know-your-customers-jobs-to-be-done\"},{\"t\":\"text\",\"v\":\" — 概念来源：要完成的进展和解决方案清单不是同一句话。本页不是该方法论教程，也不采用它的访谈步骤。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Michael Nygard：Documenting Architecture Decisions\",\"href\":\"https://cognitect.com/blog/2011/11/15/documenting-architecture-decisions\"},{\"t\":\"text\",\"v\":\" — 只取「先写下处境」。Context 在第 03 章再与决定、后果一起用。本页不把记录写成 ADR 模板。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Java\",\"href\":\"../../java/\"},{\"t\":\"text\",\"v\":\" — 已有栈的事实在主题首页。本页只把「必须守住哪一条」写成约束。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"微服务\",\"href\":\"../../microservices/\"},{\"t\":\"text\",\"v\":\" — 同上，服务侧边界。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"AI\",\"href\":\"../../ai/\"},{\"t\":\"text\",\"v\":\" — 同上，模型与应用边界。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"返回产品调研\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：对照与条件\",\"href\":\"../02-comparison/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"这一页补哪一块 {#problem-scope}\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"问题要能被判定 {#problem-question}\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"约束必须可核对 {#problem-constraints-check}\"},{\"id\":\"h-4\",\"level\":2,\"text\":\"观察、推断、决定 {#problem-sentences}\"},{\"id\":\"h-5\",\"level\":2,\"text\":\"同一句话，两种约束 {#problem-example}\"},{\"id\":\"h-6\",\"level\":2,\"text\":\"常见误读 {#problem-misreadings}\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"可选核对 {#problem-check}\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"资料索引 {#problem-sources}\"}]},\"product-research/02-comparison\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"产品调研\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 对照与条件\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"对照只在同一类问题、同一组约束下成立。单位不同，或证据不能核，结论就没有意义。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"这一页补哪一块 {#comparison-scope}\",\"id\":\"h-1\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"问题与约束\",\"href\":\"../01-problem-constraints/\"},{\"t\":\"text\",\"v\":\" 写下要决定什么、必须守住什么。本页只写备选怎样放在那一组条件下比较。不写成竞品功能目录，不教市场占有率，也不新写协议或安全课。技术边界只在例子需要时回链。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"单位必须相同 {#comparison-unit}\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"对照的单位是：同一个问题，同一组约束，各方用什么手段、付出什么代价、哪些约束被满足或被绕开。把 A 的宣传句子和 B 的实现细节并排，比的不是同一类东西。单位不同，后面的打分或排序都没有共同含义。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"功能清单不是对照。清单只说「有没有某项」。对照要说：在第 01 章的问题下，这项手段对那条约束做了什么。没有这个问题和这组约束，多出来的功能不能说明更适合。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"每条对照都要能核 {#comparison-evidence}\",\"id\":\"h-3\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"写下来的每一条都要带三样：版本或观测日期、适用场景、证据出处。没有日期和出处的「对方有某某功能」，不能进入选型。出处可以是对方当时的公开说明，或一次注明日期的观察。官网上的一句话只是一条观察，而且只在那个日期成立。它不等于已经按第 01 章的约束验证过。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本站知识正文要求资料索引对得上断言，事实带日期。对照记录沿用同一条：没有出处和日期的句子，不配和有出处的句子放在同一张表里。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"不可比是一条合法记录 {#comparison-incomparable}\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"下面三种要显式标成不可比，而不是凑一个分数。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"问题不同。一个在解决当场提交，一个在解决路上阅读。都叫「离线」也不能并排。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"约束不同。一个必须守住已有的运行环境，一个可以换一整套栈。手段不可比。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"证据不可核。只有演示，或页面已经过期、看不到当时的版本。看不到，就写「不可核」，不要补成「大概有」。\"}],\"n\":3}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"标成不可比本身就是记录。它告诉后来的人：这里停过，不是没看见。强行打分会把这个停顿抹掉。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"条件一换，结论就换 {#comparison-example}\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"两款做法都能让人「登录」。第 01 章的约束若是「要避免跨源脚本读走会话」，对照就不能停在「都能登录」。\"}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"做法甲把会话放在浏览器按源隔开的存储里。脚本默认可读的范围由源决定。这条约束被它的存放方式接住。事实见 \"},{\"t\":\"link\",\"v\":\"浏览器里的源\",\"href\":\"../../web/origin/\"},{\"t\":\"text\",\"v\":\"，本页不重讲三元组。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"做法乙把令牌放进页面里任意脚本都能读的存储。登录仍然完成，但这条约束没有被接住。跨源脚本能否读到，仍是源的规则，不是「有登录功能」能代替的。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"在这条约束下，甲满足、乙绕开或未满足。若约束改成「只要能认出同一个账号」，两者又可能都算满足。条件没写，就无法知道当时比的是哪一种。本页不给这两种做法起产品名，也不把它写成安全课。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"常见误读 {#comparison-misreadings}\",\"id\":\"h-6\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"「功能多的就是更适合的方案。」多出来的功能若不对着第 01 章的问题和约束，就不在这次对照的单位里。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「官网写了就等于已经验证。」官网句子是一条带日期的观察。它还没有按本次约束被核过。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「同一品类就可以直接打分，不必写条件。」品类相同不保证问题相同、约束相同。没有条件的分数没有共同单位。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「找不到完全对等的竞品，对照就无法开始。」对等不是前提。不可比要标出来。能核的那几条仍可以记，不能核的不打分。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"可选核对 {#comparison-check}\",\"id\":\"h-7\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"单位和证据已经分开。这两问只核对一条对照能不能进入下一章。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"表上写「对方支持离线」，没有日期、没有出处、也没写是哪种离线。它能进入选型吗？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"两个方案的问题不同。为了得到一个名次，把它们打成 8 分和 6 分。这是对照还是抹掉不可比？\"}],\"n\":2}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"不能。没有日期和出处，也没有落到第 01 章的哪一种约束。它还不是一条可核的对照。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"是抹掉不可比。问题不同就应当标成不可比。分数让人以为它们有共同单位。\"}],\"n\":2}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引 {#comparison-sources}\",\"id\":\"h-8\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"英国政府 Technology Code of Practice\",\"href\":\"https://www.gov.uk/guidance/the-technology-code-of-practice\"},{\"t\":\"text\",\"v\":\" — 概念来源：先写清需要，再按需要选择，而不是按功能多少或是否流行。本页不采用其采购流程。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"展示规范：资料索引\",\"href\":\"../../../STYLE.md\"},{\"t\":\"text\",\"v\":\" — 本站约定：断言要能在资料索引里找到来源。对照记录的日期和出处沿用这一条，不另造一套。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"问题与约束\",\"href\":\"../01-problem-constraints/\"},{\"t\":\"text\",\"v\":\" — 对照所用的问题和约束从这里来。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"浏览器里的源\",\"href\":\"../../web/origin/\"},{\"t\":\"text\",\"v\":\" — 例子里「会话放在按源隔开的存储」这一事实。本页只演示条件如何改变对照。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：问题与约束\",\"href\":\"../01-problem-constraints/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回产品调研\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：选型记录\",\"href\":\"../03-selection-records/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"这一页补哪一块 {#comparison-scope}\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"单位必须相同 {#comparison-unit}\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"每条对照都要能核 {#comparison-evidence}\"},{\"id\":\"h-4\",\"level\":2,\"text\":\"不可比是一条合法记录 {#comparison-incomparable}\"},{\"id\":\"h-5\",\"level\":2,\"text\":\"条件一换，结论就换 {#comparison-example}\"},{\"id\":\"h-6\",\"level\":2,\"text\":\"常见误读 {#comparison-misreadings}\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"可选核对 {#comparison-check}\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"资料索引 {#comparison-sources}\"}]},\"product-research/03-selection-records\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"产品调研\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 选型记录\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"选型记录是一次带日期的取舍：问题、备选、判据、结果、依据，以及没选什么。它不是新的真理，也不是把技术章再抄一遍。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"这一页补哪一块 {#selection-scope}\",\"id\":\"h-1\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"问题与约束\",\"href\":\"../01-problem-constraints/\"},{\"t\":\"text\",\"v\":\" 给出要决定的问题和必须守住的条件。\"},{\"t\":\"link\",\"v\":\"对照与条件\",\"href\":\"../02-comparison/\"},{\"t\":\"text\",\"v\":\" 给出在那些条件下哪些做法可比、哪些不可比。本页只写取舍如何留下来。不写成架构决策记录的格式教程，不规定文件名、编号或仓库布局，也不重写任何技术栈。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"记录里不能少的几项 {#selection-parts}\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"一份选型记录至少包含这些，少一项就核不全：\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"要决定的问题，回链第 01 章，而不是另写一个愿望。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"纳入的备选。包括最后没选的。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"共同的判据，并且与第 01 章的约束对齐。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"取舍结果：选了哪一个。\"}],\"n\":4},{\"inlines\":[{\"t\":\"text\",\"v\":\"当时依据的事实：链到已有技术章或外部来源，不在本页复述。\"}],\"n\":5},{\"inlines\":[{\"t\":\"text\",\"v\":\"明确未选的东西，以及理由。\"}],\"n\":6}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"缺了「未选什么」，后来的人无法判断是没看见，还是看过并拒绝。只写「我们决定用 X」，把这六项收成了一句口号。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"判据先于结果 {#selection-criteria}\",\"id\":\"h-3\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"判据必须先于结果写下。它回答的是：在已经写明的约束下，用什么来区分备选。先定结果再补判据，记录就失去核验价值。任何人都能为已经做出的选择找一组刚好成立的理由。先写下判据，结果才是这些判据的一次应用，而不是事后的说明。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"判据对齐约束，而不是对齐宣传。第 01 章若写了「必须跑在已有的 JVM 服务里」，判据里就应有这一条，并且链到 \"},{\"t\":\"link\",\"v\":\"Java\",\"href\":\"../../java/\"},{\"t\":\"text\",\"v\":\" 里那条事实。本页只记录这条事实如何进入判据，不把 Java 章抄进来。「把技术章抄进调研才算有依据」会把事实和判断再次混成一篇。事实留在原处，记录只留指针和它在这次判据里的角色。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"记录有时间 {#selection-dated}\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"选型是带日期的判断，不是新的真理。同一问题在约束变化后可以有另一份记录。上一份的问题、判据和结果不许悄悄改掉。怎样追加、怎样指向被取代者，是 \"},{\"t\":\"link\",\"v\":\"失效与修订\",\"href\":\"../04-invalidation/\"},{\"t\":\"text\",\"v\":\" 的事。本页先把「这份记录有时间」写清：日期属于记录本身，不属于后来补上的感想。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"有一份决策模板，或某公司的决策文档，不等于这里的六项都在，更不等于判据先于结果。模板可以提醒栏目。栏目空着，或结果写在判据之前，记录仍然不能核。本页借用的是「处境、决定、后果，以及后来可以被取代」这一结构，不要求本仓库改成 ADR 文件。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"一次取舍，不展开框架 {#selection-example}\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"约束来自第 01 章，并链到已有事实：已经有 Java 服务（\"},{\"t\":\"link\",\"v\":\"Java\",\"href\":\"../../java/\"},{\"t\":\"text\",\"v\":\"），需要浏览器里的客户端，并且不新开一门协议课（\"},{\"t\":\"link\",\"v\":\"Web\",\"href\":\"../../web/\"},{\"t\":\"text\",\"v\":\" 已有的边界就够用）。备选只有两个，单位相同。\"}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"备选甲：服务器生成第一份 HTML，浏览器展示这份文档。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"备选乙：浏览器持有状态再推导界面，接口留在同一源。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"判据先写下，并且只来自约束：不新增协议章；浏览器与接口的源关系必须能回到 \"},{\"t\":\"link\",\"v\":\"Web\",\"href\":\"../../web/\"},{\"t\":\"text\",\"v\":\" 已写的约定；实现落在已有的 JVM 服务上，而不是另起一个运行时。对照若发现某一条证据不可核，按第 02 章标成不可比，不打分。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"结果可以是选甲或选乙。记录必须写下没选的那一个，以及它在哪一条判据上未满足或代价更高。例如没选乙，是因为当时的约束要求第一份文档由已有服务生成，而不是因为「单页比较新」。框架名字不进入这条记录。它们不是这次的判据。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"常见误读 {#selection-misreadings}\",\"id\":\"h-6\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"「选型就是写一句『我们决定用 X』。」没有备选、判据、事实指针和未选项，这句话不能核。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「把技术章抄进调研，才算有依据。」依据是指针和它在判据里的角色。复述会把事实写成好像是这次调研新发现的。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「备选只写最后赢家即可。」没有未选项，后来的人分不清是拒绝过还是没看过。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「有了 ADR 模板或某公司的决策文档，就等于有了可核记录。」模板不代替判据先于结果，也不代替日期和事实指针。本仓库也不因此改成 ADR 布局。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"可选核对 {#selection-check}\",\"id\":\"h-7\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"六项已经列在上面。这两问只核对记录能不能被后来的人核。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"记录写着「决定采用服务端生成的 HTML」，日期在结果之后才补上判据。它还有核验价值吗？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"备选只写了赢家，并附上整章 Java 笔记的抄录。未选项在哪里？依据算写清了吗？\"}],\"n\":2}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"没有。判据若在结果之后补写，就不再是这次取舍事先遵守的条件。日期也说明不了判据当时就在。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"未选项缺失，所以分不清没看见还是拒绝了。整章抄录不是依据。依据应是指向 Java 或 Web 已有边界的指针，以及这条事实进入了哪一条判据。\"}],\"n\":2}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引 {#selection-sources}\",\"id\":\"h-8\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"Michael Nygard：Documenting Architecture Decisions\",\"href\":\"https://cognitect.com/blog/2011/11/15/documenting-architecture-decisions\"},{\"t\":\"text\",\"v\":\" — 概念来源：Context、Decision、Consequences，以及记录可被后续查阅、并可被取代。本页借「为什么这样记」，不规定文件名、编号或仓库布局，也不把产品调研写成架构档案系统。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"问题与约束\",\"href\":\"../01-problem-constraints/\"},{\"t\":\"text\",\"v\":\" — 要决定的问题和约束。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"对照与条件\",\"href\":\"../02-comparison/\"},{\"t\":\"text\",\"v\":\" — 哪些备选可比、哪些应标成不可比。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Web\",\"href\":\"../../web/\"},{\"t\":\"text\",\"v\":\" — 例子里的浏览器与接口边界。事实留在那里。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Java\",\"href\":\"../../java/\"},{\"t\":\"text\",\"v\":\" — 例子里「已有 JVM 服务」这一事实。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"微服务\",\"href\":\"../../microservices/\"},{\"t\":\"text\",\"v\":\" — 若判据用到服务侧边界，只作事实来源。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"AI\",\"href\":\"../../ai/\"},{\"t\":\"text\",\"v\":\" — 若判据用到模型或应用边界，只作事实来源。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"DevOps\",\"href\":\"../../devops/\"},{\"t\":\"text\",\"v\":\" — 若判据用到流水线保证，只作事实来源。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：对照与条件\",\"href\":\"../02-comparison/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回产品调研\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：失效与修订\",\"href\":\"../04-invalidation/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"这一页补哪一块 {#selection-scope}\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"记录里不能少的几项 {#selection-parts}\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"判据先于结果 {#selection-criteria}\"},{\"id\":\"h-4\",\"level\":2,\"text\":\"记录有时间 {#selection-dated}\"},{\"id\":\"h-5\",\"level\":2,\"text\":\"一次取舍，不展开框架 {#selection-example}\"},{\"id\":\"h-6\",\"level\":2,\"text\":\"常见误读 {#selection-misreadings}\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"可选核对 {#selection-check}\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"资料索引 {#selection-sources}\"}]},\"product-research/04-invalidation\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"产品调研\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 失效与修订\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"记录要预先写明自己在什么条件下不再成立。条件到了，就另开一份并指向旧的，而不是改掉当时的判断。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"这一页补哪一块 {#invalidation-scope}\",\"id\":\"h-1\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"选型记录\",\"href\":\"../03-selection-records/\"},{\"t\":\"text\",\"v\":\" 把一次取舍写成有时间的六项。本页只写这份记录如何失效、如何被取代，同时留下当时的判断。不写成项目管理流程，不教发布节奏，也不规定用 Git 的哪一种命令。痕迹可查时，用法见 \"},{\"t\":\"link\",\"v\":\"Git 版本控制\",\"href\":\"../../cs-basics/04-git/\"},{\"t\":\"text\",\"v\":\"，本页不重讲。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"失效条件要先写出来 {#invalidation-conditions}\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"失效条件写在记录里，哪怕当时觉得不太可能。常见的是这四类：\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"约束变了。第 01 章必须守住的条件不再是那一条。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"依据的事实变了。所依赖的版本边界更新了，或那一章撤回了某条保证。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"对照所用的证据过期，或被推翻。当时的出处不再描述现在的对象。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"问题本身被重写。要改变的事或「怎样算解决」换了，旧的对照单位就不成立。\"}],\"n\":4}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这四类是连接何时断开的说明，不是追责。一份在其条件下正确的记录，可以在条件改变后被新记录取代。旧的问题、判据和结果留着，并写清它在哪一条上不再适用。当时记对了，和现在还是否适用，是两件事。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"追加，而不是改掉 {#invalidation-append}\",\"id\":\"h-3\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"修订的合法方式是追加，或另开一份，并指向被取代者。直接改掉原结论、不留痕迹，第 03 章的「可核对」就落空：后来的人看见的只有新结论，看不见当时的判据。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"被取代是一种状态，不是删除。新记录写明自己取代哪一份、击中了哪一条失效条件、新的对照或判据是什么。旧记录保持可读。这里只定这个原则，不规定文件名，也不规定用 Git 的哪一种操作。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"新技术发布了，旧选型不因此自动作废。要看第 01 章的约束和第 03 章的判据是否真的被击中。没有被击中，就只是一条新的事实，还不是这份记录的失效。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"引用的技术章变了，记录要重核 {#invalidation-facts}\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"选型记录里的事实是指针，不是抄来的正文。所指向的技术章若更新了版本基线，或撤回了某条保证，这份选型要被重新核验，而不是自动继续有效。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"版本基线带日期，是本站技术章已经在用的写法，例如 \"},{\"t\":\"link\",\"v\":\"Java\",\"href\":\"../../java/\"},{\"t\":\"text\",\"v\":\" 主题页上的版本说明。日期变了，只说明事实可能变了，选型是否失效仍看判据有没有用到那一条。\"},{\"t\":\"link\",\"v\":\"DevOps\",\"href\":\"../../devops/\"},{\"t\":\"text\",\"v\":\" 里的来源证据也是带时间的陈述：标签可以改指向，摘要上的陈述才是当时承认的那一份。证据过期，不等于当时的选型记错，但继续沿用之前要再核一次。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"约束击中「同一源」 {#invalidation-example}\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"当初的选型按这个约束做：浏览器里的页面和它调用的接口留在同一源，因此可以在「服务器生成第一份 HTML」和「浏览器持有状态、接口仍同源」之间取舍。判据指向 \"},{\"t\":\"link\",\"v\":\"Web\",\"href\":\"../../web/\"},{\"t\":\"text\",\"v\":\" 已写的边界，不依赖把 API 放到另一台主机。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"后来的约束变成：接口必须拆到另一个主机。被击中的是「同一源」那一条，不是「用了哪一个框架」。旧记录在原来的约束下仍然成立，只是不再适用于新约束。新记录要做的是一次新的对照：跨源时脚本还能不能读到响应、凭证落在哪一侧。事实在 \"},{\"t\":\"link\",\"v\":\"跨越源边界\",\"href\":\"../../web/04-crossing-boundary/\"},{\"t\":\"text\",\"v\":\"。本页不重讲 CORS。新记录指向旧记录，写明取代原因是这条约束变了，并补上这次对照的日期和出处。把旧结论改成「当时就选了跨源」是抹掉，不是修订。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"常见误读 {#invalidation-misreadings}\",\"id\":\"h-6\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"「决策一旦写下就永远有效。」记录在写下的条件下成立。约束、事实、证据或问题变了，适用性就要重核。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「条件变了，直接改原文就行。」改掉原结论而不留旧的问题和判据，后来的人无法再核当时为什么那样选。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「新技术发布了，旧选型就自动作废。」只有它击中了当时的约束或判据，这份记录才失效。否则它只是一条尚未进入判据的新事实。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「失效是在追责，不是在更新连接。」失效写的是哪一条连接断开了。它不把当时的判断改写成错误，除非当时的事实或推理本身不成立。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"可选核对 {#invalidation-check}\",\"id\":\"h-7\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"取代和抹掉已经分开。这两问只核对旧记录还要不要留。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"所依赖的 Java 版本基线日期更新了，但当时的判据没有用到那一条版本差异。旧选型因此作废了吗？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"接口改到另一主机之后，有人把旧记录里的结论改成「选择跨源 BFF」，不保留原文。这是修订吗？\"}],\"n\":2}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"没有。事实变了，但判据没被击中。应当记下这条新事实，并写明它尚未使这份记录失效。自动作废会把没被用到的变化当成断连。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"不是。这是抹掉。修订应另开一份，指向旧记录，写明「同一源」这条约束不再成立，并补上新的对照。旧的问题和结果仍要能读到。\"}],\"n\":2}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引 {#invalidation-sources}\",\"id\":\"h-8\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"Michael Nygard：Documenting Architecture Decisions\",\"href\":\"https://cognitect.com/blog/2011/11/15/documenting-architecture-decisions\"},{\"t\":\"text\",\"v\":\" — 记录可以标成被取代（superseded），后果仍留在原记录里。本页只取这个状态，不引入另一套变更管理框架，也不规定文件名。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Java\",\"href\":\"../../java/\"},{\"t\":\"text\",\"v\":\" — 版本说明带日期。日期更新是「事实可能变了」的信号，不是选型自动作废。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"DevOps：来源与追溯\",\"href\":\"../../devops/02-provenance/\"},{\"t\":\"text\",\"v\":\" — 来源陈述有时间，标签可以改指向。证据过期后要再核，而不是当作当时记错。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"跨越源边界\",\"href\":\"../../web/04-crossing-boundary/\"},{\"t\":\"text\",\"v\":\" — 例子里「接口换主机之后，脚本可读性和信任落点变了」这一事实。本页不重讲。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"选型记录\",\"href\":\"../03-selection-records/\"},{\"t\":\"text\",\"v\":\" — 被取代的是那一份有时间的取舍。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Git 版本控制\",\"href\":\"../../cs-basics/04-git/\"},{\"t\":\"text\",\"v\":\" — 只在需要「痕迹可查」时回链。本页不规定用哪一种 Git 操作。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：选型记录\",\"href\":\"../03-selection-records/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回产品调研\",\"href\":\"../\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"这一页补哪一块 {#invalidation-scope}\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"失效条件要先写出来 {#invalidation-conditions}\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"追加，而不是改掉 {#invalidation-append}\"},{\"id\":\"h-4\",\"level\":2,\"text\":\"引用的技术章变了，记录要重核 {#invalidation-facts}\"},{\"id\":\"h-5\",\"level\":2,\"text\":\"约束击中「同一源」 {#invalidation-example}\"},{\"id\":\"h-6\",\"level\":2,\"text\":\"常见误读 {#invalidation-misreadings}\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"可选核对 {#invalidation-check}\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"资料索引 {#invalidation-sources}\"}]}}}");
